import { Address } from '@ton/core';
import { useCallback, useEffect, useState } from 'react';
import { useRecoilCallback, useRecoilValueLoadable } from 'recoil';
import {
  jettonWalletsAtom,
  jettonWalletsSelector,
  pushToSnacks,
  snacksAtom,
  tonClientSelector,
} from '../state';
import { JettonWalletItem, SmcType } from '../types';
import { getAddress, getJettonAddress, getJettonBalance } from '../utils';
import { useInterval } from './useInterval';

type Props = {
  smc: SmcType;
  minter?: string;
  wallet?: string;
  balanceTtl?: number;
};

export function useJettonWallet({ smc, minter, wallet, balanceTtl }: Props) {
  const { contents, state } = useRecoilValueLoadable(jettonWalletsSelector({ minter, wallet }));
  const [data, setData] = useState<JettonWalletItem>();
  const [pending, setPending] = useState(false);
  const fetchJettonWallet = useRecoilCallback(
    ({ snapshot, set }) =>
      async (smc: SmcType, minter: Address, address: Address) => {
        const client = await snapshot.getPromise(tonClientSelector);
        const jetton = await getJettonAddress(client, minter, address);
        if (!jetton) {
          set(
            snacksAtom,
            pushToSnacks({
              id: `${minter}-${address}-jetton-address-error`,
              color: 'neutral',
              title: 'Info',
              body: 'Unable to get jetton wallet address',
            }),
          );
          return;
        }
        const balance = await getJettonBalance(client, jetton, smc).catch((e: Error) =>
          set(
            snacksAtom,
            pushToSnacks({
              id: `${minter}-${address}-${jetton}-balance-error`,
              color: 'neutral',
              title: e.message,
              body: `You have no ${smc} transactions`,
            }),
          ),
        );
        const jettonWalletItem: JettonWalletItem = {
          smc,
          wallet: address.toString(),
          minter: minter.toString(),
          jetton: jetton.toString(),
          balance: {
            ...(balance ? balance : { value: 0n }),
            timestamp: Date.now(),
          },
        };
        set(jettonWalletsAtom, (v) => [
          ...v?.filter(
            (f) => !(getAddress(f.minter)?.equals(minter) && getAddress(f.wallet)?.equals(address)),
          ),
          jettonWalletItem,
        ]);
      },
  );
  const refetchJettonBalance = useRecoilCallback(
    ({ snapshot, set }) =>
      async ({ smc, wallet, minter, jetton }: JettonWalletItem) => {
        const minterA = getAddress(minter);
        if (!minterA) return;
        const walletA = getAddress(wallet);
        if (!walletA) return;
        const jettonA = getAddress(jetton);
        if (!jettonA) return;
        const client = await snapshot.getPromise(tonClientSelector);
        const balance = await getJettonBalance(client, jettonA, smc).catch((e: Error) =>
          set(
            snacksAtom,
            pushToSnacks({
              id: `${minter}-${wallet}-${jetton}-balance-error`,
              color: 'neutral',
              title: e.message,
              body: `You have no ${smc} transactions`,
            }),
          ),
        );
        if (!balance) {
          return;
        }
        const jettonWalletItem: JettonWalletItem = {
          smc,
          wallet,
          minter,
          jetton,
          balance: {
            ...balance,
            timestamp: Date.now(),
          },
        };
        set(jettonWalletsAtom, (v) => [
          ...v?.filter(
            (f) =>
              !(getAddress(f.minter)?.equals(minterA) && getAddress(f.wallet)?.equals(walletA)),
          ),
          jettonWalletItem,
        ]);
      },
    [],
  );

  useEffect(() => {
    if (!wallet || !minter || pending) return;
    switch (state) {
      case 'hasValue': {
        if (contents) {
          setData(contents);
          const avgExecutionTime = 3e3;
          // NOTE: return if we doesn't need to refetch stale data
          if (
            !balanceTtl ||
            Date.now() - avgExecutionTime < contents.balance.timestamp + balanceTtl
          ) {
            return;
          }
        }

        const minterA = getAddress(minter);
        if (!minterA) return;
        const walletA = getAddress(wallet);
        if (!walletA) return;

        setPending(true);
        fetchJettonWallet(smc, minterA, walletA).finally(() => setPending(false));
        break;
      }
      case 'hasError':
      case 'loading':
      default:
        setData(undefined);
        break;
    }
  }, [wallet, contents, state, pending]);

  // refetch only balance without touching jetton wallet address
  const refetchBalance = useCallback(() => {
    if (!data) return;
    setPending(true);
    refetchJettonBalance(data).finally(() => setPending(false));
  }, [data]);

  // NOTE: refetch expired by ttl balances
  useInterval(refetchBalance, wallet && typeof balanceTtl !== 'undefined' ? balanceTtl : null);

  return { state, data, pending, refetchBalance };
}
