import { atom } from 'recoil';
import { SNACKS_MAX_LENGTH } from '../constants';
import { SnackData } from '../types';
import { uuidv4 } from '../utils';

export const snacksAtom = atom<SnackData[]>({
  key: 'snacksAtom',
  default: [],
});

export const lastSnackIdAtom = atom<SnackData['id'] | undefined>({
  key: 'lastSnackIdAtom',
  default: undefined,
});

export const pushToSnacks =
  ({ id, timestamp, ...props }: Partial<SnackData>) =>
  (currVal: SnackData[]): SnackData[] => [
    ...currVal.slice(SNACKS_MAX_LENGTH),
    {
      id: id || uuidv4(),
      timestamp: timestamp || Date.now(),
      ...props,
    } as SnackData,
  ];
