import { Box, Button, Stack, Typography } from '@mui/joy';
import { initData, invoice, InvoiceStatus } from '@telegram-apps/sdk-react';
import { useTonConnectModal } from '@tonconnect/ui-react';
import { useCallback, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useSetRecoilState } from 'recoil';
import { WorkspaceNext } from '../workspace-next';
import { FaucetIcon } from './faucet-icon';
import { api } from '/src/constants';
import { useActiveWallet } from '/src/hooks/useActiveWallet';
import { metricsAtom } from '/src/state';
import {
  isFaucetInvoiceResponse,
  isOpenedInvoiceResponse,
  OpenedInvoiceResponse,
} from '/src/types';
import { delay } from '/src/utils';

// export const FaucetScreen = () => (isUnderTelegramWebview ? <OpenFaucet /> : <FaucetForBrowsers />);
export const FaucetScreen = () => <OpenFaucet />;

const OpenFaucet = () => {
  const { t } = useTranslation();
  const { open: openTonConnectModal } = useTonConnectModal();
  const setMetrics = useSetRecoilState(metricsAtom);
  const { walletRestored } = useActiveWallet();
  const [sendingData, setSendingData] = useState(false);
  const [openedInvoice, setOpenedInvoice] = useState<OpenedInvoiceResponse>();
  const [invoiceStatus, setInvoiceStatus] = useState<InvoiceStatus>();
  const openFaucetHandler = useCallback(async () => {
    if (!walletRestored) return;
    if (!openedInvoice) return;
    if (invoice.isOpened()) return;

    let sendFail = false;
    setSendingData(true);
    try {
      let invoiceUrl: string | undefined;
      const rawJson = await getInvoiceLink(openedInvoice.id);
      if (isFaucetInvoiceResponse(rawJson)) {
        invoiceUrl = rawJson.invoice;
      }
      if (!invoiceUrl) throw new Error('fail to get invoice url');
      const status = await invoice.open(invoiceUrl, 'url');
      setInvoiceStatus(status);
      if (status === 'paid') {
        setMetrics((v) => ({ ...v, faucet: { stars: 1, sp: '8' } }));
      }
    } catch (error) {
      sendFail = true;
    }

    if (sendFail) {
      setSendingData(false);
      return;
    }

    try {
      await delay(1e3);
    } catch (error) {}

    setSendingData(false);
  }, [walletRestored, openedInvoice, invoice]);

  useEffect(() => {
    if (!walletRestored) return;
    const user = initData.user();
    if (!user) return;

    (async () => {
      try {
        const rawJson = await getOpenInvoice(user.id, walletRestored.address);
        if (isOpenedInvoiceResponse(rawJson)) {
          setOpenedInvoice(rawJson);
        }
      } catch (error) {
        console.log('openInvoice error', error);
      }
    })();
  }, [walletRestored]);

  return (
    <WorkspaceNext>
      <Stack spacing={2}>
        <FaucetIcon />
        {invoiceStatus === 'paid' ? (
          <Box>
            <Typography level="h3">{t('faucet.await-your-sp-title')}</Typography>
            <Typography level="body-sm">{t('faucet.await-your-sp-subtitle')}</Typography>
          </Box>
        ) : openedInvoice ? (
          <Box>
            <Typography level="h3">{t('faucet.title')}</Typography>
            <Typography level="body-sm">{t('faucet.subtitle')}</Typography>
          </Box>
        ) : (
          <Box>
            <Typography level="h3">{t('faucet.exceeded-title')}</Typography>
            <Typography level="body-sm">{t('faucet.exceeded-subtitle')}</Typography>
          </Box>
        )}
        {walletRestored ? (
          <Button
            size="lg"
            type="submit"
            loading={sendingData}
            disabled={!walletRestored || invoiceStatus === 'paid' || !openedInvoice}
            onClick={() => openFaucetHandler()}
          >
            {t('faucet.buy')}
          </Button>
        ) : (
          <Button onClick={() => openTonConnectModal()}>{t('connect-wallet')}</Button>
        )}
      </Stack>
    </WorkspaceNext>
  );
};

const getOpenInvoice = async (userId: number, wallet: string) =>
  fetch(`${api.baseUrl}/api/v1/telegram/open-invoice`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ userId, wallet }),
  }).then((r) => {
    if (!r.ok) {
      throw new Error(r.statusText);
    }
    return r.json();
  });

const getInvoiceLink = async (id: string) =>
  fetch(`${api.baseUrl}/api/v1/telegram/invoice/${id}`, {
    method: 'GET',
    headers: { 'Content-Type': 'application/json' },
  }).then((r) => {
    if (!r.ok) {
      throw new Error(r.statusText);
    }
    return r.json();
  });
