import { Add, Tune, Wallet } from '@mui/icons-material';
import {
  Chip,
  Dropdown,
  IconButton,
  ListDivider,
  ListItem,
  ListItemDecorator,
  Menu,
  MenuButton,
  MenuItem,
  MenuItemProps,
  Stack,
  Typography,
} from '@mui/joy';
import { useCallback, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useRecoilState, useSetRecoilState } from 'recoil';
import { api } from '../constants';
import {
  addWalletModalAtom,
  pushToSnacks,
  snacksAtom,
  walletsAtom,
  walletSettingModalAtom,
} from '../state';
import { WalletItem, WalletType } from '../types';
import { getAddress, isTmaMobileDevice, truncateLong } from '../utils';

export const WalletMenuBar = () => {
  const { t } = useTranslation();
  const [myWallets, setMyWallets] = useRecoilState(walletsAtom);
  const setSnacks = useSetRecoilState(snacksAtom);
  const setOpenAddWallet = useSetRecoilState(addWalletModalAtom);
  const setWalletSettingModal = useSetRecoilState(walletSettingModalAtom);
  const wallet = myWallets.find((f) => f.active);
  const otherWallets = myWallets.filter((f) => !f.active);
  const friendlyAddress = useMemo(() => {
    if (!wallet) return '';
    const address = getAddress(wallet.address);
    if (!address) return '';
    return address.toString();
  }, [wallet]);
  const [openMenu, setOpenMenu] = useState(false);
  const handleOpenMenuChange = useCallback(
    (event: React.SyntheticEvent | null, isOpen: boolean) => {
      setOpenMenu(isOpen);
    },
    [],
  );
  const handleActivateWallet = useCallback(
    (a: string) => setMyWallets((v) => [...v.map((m) => ({ ...m, active: m.address == a }))]),
    [setMyWallets],
  );
  const maxWallets = useMemo(() => myWallets.length > 5, [myWallets]);
  const isMobileDevice = useMemo(() => isTmaMobileDevice(), []);
  const canAddMore = !maxWallets && isMobileDevice;

  return (
    <Dropdown open={openMenu} onOpenChange={handleOpenMenuChange}>
      <MenuButton
        disabled={myWallets.length == 0}
        slots={{ root: IconButton }}
        slotProps={{ root: { variant: 'outlined', color: 'neutral' } }}
        sx={{ maxWidth: 128 }}
        endDecorator={wallet && <Wallet />}
      >
        {wallet ? (
          <Typography level="body-sm" noWrap sx={{ pr: 0.5 }}>
            {wallet.name}
          </Typography>
        ) : (
          <Wallet />
        )}
      </MenuButton>
      <Menu
        variant="outlined"
        // open
        placement="bottom-start"
        disablePortal
        size="sm"
        sx={{
          '--ListItemDecorator-size': '24px',
          '--ListItem-minHeight': '40px',
          '--ListDivider-gap': '4px',
          minWidth: 200,
        }}
      >
        {wallet && (
          <ListItem>
            <Stack direction="column" width="100%">
              <Stack
                direction="row"
                justifyContent="space-between"
                alignItems="center"
                gap={1}
                width="100%"
              >
                <Typography textColor="focusVisible">{wallet.name}</Typography>
                <IconButton
                  sx={{ p: 0.5, minHeight: 'unset', minWidth: 'unset' }}
                  onClick={() => setWalletSettingModal(true)}
                >
                  <Tune sx={{ width: 20, height: 20 }} />
                </IconButton>
              </Stack>
              <Typography
                onClick={() => {
                  navigator.clipboard.writeText(friendlyAddress);
                  setSnacks(
                    pushToSnacks({
                      color: 'success',
                      // title: 'Info',
                      body: 'Address copied to clipboard',
                      autoHideDuration: 1e3,
                    }),
                  );
                  setOpenMenu(false);
                }}
                textColor="text.tertiary"
                sx={{
                  '&:hover': {
                    cursor: 'pointer',
                    backgroundColor: (t) => t.palette.primary[500],
                  },
                }}
              >
                {truncateLong(friendlyAddress)}
              </Typography>
            </Stack>
          </ListItem>
        )}
        {otherWallets.length > 0 && <ListDivider />}
        {otherWallets.map((m, i) =>
          m.wallet == WalletType.tcsdk ? (
            <TonConnectMenuItem
              key={`menu-bar-wallet-item-${i}-`}
              onClick={() => handleActivateWallet(m.address)}
              wallet={m}
            />
          ) : (
            <MenuItem
              key={`menu-bar-wallet-item-${i}-`}
              onClick={() => handleActivateWallet(m.address)}
            >
              {m.name}
            </MenuItem>
          ),
        )}
        {api.isWallet3 && canAddMore && (
          <>
            <ListDivider />
            <MenuItem onClick={() => setOpenAddWallet(true)} color="primary">
              <ListItemDecorator>
                <Add />
              </ListItemDecorator>
              {t('wallets.add-wallet')}
            </MenuItem>
          </>
        )}
      </Menu>
    </Dropdown>
  );
};

const TonConnectMenuItem = ({ wallet: w, ...props }: MenuItemProps & { wallet: WalletItem }) => (
  <MenuItem {...props}>
    {w.name}
    <Chip variant="outlined" size="sm" sx={{ ml: 'auto', color: 'text.tertiary' }}>
      {w.wallet}
    </Chip>
  </MenuItem>
);
