import { atom } from 'recoil';
import { localStorageEffect } from '../effects';
import { STORAGE_APPUID_KEY } from '/src/constants';

type Metrics = {
  deeplink?: string;
  user?: string;
  wallet?: string;
  swap?: { ton: string; sp: string };
  sent?: { ticker: string; amount: string };
  simulate?: { ton: string; sp: string };
  faucet?: { stars: number; sp: string };
};

export const appUidAtom = atom<string>({
  key: 'appUidAtom',
  default: undefined,
  effects: [
    localStorageEffect<string>({
      key: STORAGE_APPUID_KEY,
      isValid: (v) => typeof v === 'string',
      defaultValue: undefined,
    }),
  ],
});
export const metricsAtom = atom<Metrics>({
  key: 'metricsAtom',
  default: undefined,
});

export const transformMetricsToYandex = ({ deeplink, user, wallet, swap, simulate }: Metrics) => {
  if (!deeplink || !user) return;
  return {
    [deeplink]: {
      [user]: {
        ts: new Date().toJSON(),
        [wallet || 'nowallet']: {
          ...(swap ? { swap: JSON.stringify(swap) } : {}),
          ...(simulate ? { simulate: JSON.stringify(simulate) } : {}),
        },
      },
    },
  };
};
