import { selector } from 'recoil';
import { api } from '../constants';
import { isTvlResponse, TvlResponse, TvlType } from '/src/types';

export const tvlSelector = selector({
  key: 'tvlSelector',
  get: async () => {
    let data: TvlResponse | undefined;
    try {
      const response = await fetch(`${api.baseUrl}/api/v2/counters/tvl/total`, {
        method: 'GET',
        headers: { 'Content-Type': 'application/json' },
      });
      const rawJson = await response.json();
      if (isTvlResponse(rawJson)) {
        data = rawJson;
      }
    } catch (err) {
      console.log(err);
      data = { tvlType: TvlType.total, value: 0 };
    }
    return data;
  },
});
