import {
  Divider,
  FormControl,
  FormHelperText,
  FormLabel,
  Modal,
  ModalClose,
  ModalDialog,
  Radio,
  RadioGroup,
  Stack,
  Switch,
  Typography,
  useColorScheme,
} from '@mui/joy';
import { Locales, useTonConnectUI } from '@tonconnect/ui-react';
import { useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useRecoilState } from 'recoil';
import { currencyAtom, zeroJettonsAtom } from '../state';
import { appCurrencies, appLanguages } from '../types';

type Props = {
  open: boolean;
  setOpen: (v: boolean) => void;
};

const themeModes = ['system', 'dark', 'light'];

export const SettingModal = ({ open, setOpen }: Props) => {
  const { t, i18n } = useTranslation();
  const { mode, setMode } = useColorScheme();
  const [_, setOptions] = useTonConnectUI();
  const [showZeros, setShowZeros] = useRecoilState(zeroJettonsAtom);
  const [currency, setCurrency] = useRecoilState(currencyAtom);

  useEffect(() => {
    setOptions({ language: i18n.language as Locales });
  }, [i18n.language]);

  return (
    <Modal open={open} onClose={() => setOpen(false)}>
      <ModalDialog>
        <ModalClose />
        <Typography level="h3">{t('settings')}</Typography>
        <Divider />
        <Stack
          gap={1}
          overflow="scroll"
          sx={{
            mx: 'calc(-1 * var(--Card-padding))',
            mb: 'calc(-1 * var(--Card-padding))',
            px: 'var(--Card-padding)',
            pb: 'var(--Card-padding)',
          }}
        >
          <FormControl>
            <FormLabel>{t('language.title')}</FormLabel>
            <RadioGroup
              defaultValue={i18n.language}
              name="lang-mode"
              onChange={(e) => i18n.changeLanguage(e.target.value)}
            >
              {appLanguages.map((m) => (
                <Radio
                  key={`lang-radio-${m}`}
                  value={m}
                  label={t(`language.list.${m}`)}
                  variant="outlined"
                />
              ))}
            </RadioGroup>
          </FormControl>
          <Divider />
          <FormControl>
            <FormLabel>{t('theme')}</FormLabel>
            <RadioGroup
              defaultValue={mode}
              name="theme-mode"
              onChange={(e) => setMode(e.target.value as any)}
            >
              {themeModes.map((m) => (
                <Radio
                  key={`theme-radio-${m}`}
                  value={m}
                  label={t(`themes.${m}`)}
                  variant="outlined"
                />
              ))}
            </RadioGroup>
          </FormControl>
          <Divider />
          <FormControl>
            <FormLabel>{t('currency.title')}</FormLabel>
            <RadioGroup
              defaultValue={currency}
              name="currency-mode"
              onChange={(e) => setCurrency(e.target.value as any)}
            >
              {Object.keys(appCurrencies).map((m) => (
                <Radio key={`currency-radio-${m}`} value={m} label={`${m}`} variant="outlined" />
              ))}
            </RadioGroup>
          </FormControl>
          <Divider />
          <FormControl orientation="horizontal" sx={{ justifyContent: 'space-between', gap: 2 }}>
            <div>
              <FormLabel>{t('show-zeros')}</FormLabel>
              <FormHelperText
                component="div"
                onClick={() => setShowZeros(!showZeros)}
                sx={{ mt: 0 }}
              >
                {t('display-jettons-with-zero')}
              </FormHelperText>
            </div>
            <Switch
              checked={showZeros}
              onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
                setShowZeros(event.target.checked)
              }
              color={showZeros ? 'success' : 'neutral'}
              variant={showZeros ? 'solid' : 'outlined'}
              slotProps={{
                endDecorator: {
                  sx: {
                    minWidth: 24,
                  },
                },
              }}
            />
          </FormControl>
        </Stack>
      </ModalDialog>
    </Modal>
  );
};
