import { Error, InfoOutlined } from '@mui/icons-material';
import {
  DialogTitle,
  Divider,
  List,
  ListItem,
  ListItemContent,
  ListItemDecorator,
  Modal,
  ModalClose,
  ModalDialog,
  Typography,
} from '@mui/joy';
import { useTranslation } from 'react-i18next';
import { spDayjs } from '../libs';
import { SnackData } from '../types';

type Props = {
  open: boolean;
  setOpen: (v: boolean) => void;
  data: SnackData[];
};

export const ModalSnacks = ({ open, setOpen, data }: Props) => {
  const { t } = useTranslation();

  return (
    <Modal open={open} onClose={() => setOpen(false)}>
      <ModalDialog
        sx={(theme) => ({
          [theme.breakpoints.only('xs')]: {
            top: 0,
            bottom: 'unset',
            left: 0,
            right: 0,
            borderRadius: 0,
            transform: 'none',
            maxWidth: 'unset',
          },
        })}
      >
        <ModalClose />
        <DialogTitle>{t('modal.snacks.title')}</DialogTitle>
        {/* <DialogContent>{t('modal.snacks.description')}</DialogContent> */}
        <List
          sx={{
            mx: 'calc(-1 * var(--ModalDialog-padding))',
            px: 'var(--ModalDialog-padding)',
            overflow: 'scroll',
          }}
        >
          {data.reverse().map((m) => (
            <ListItem key={m.id} color={m.color} variant={m.variant || 'soft'}>
              <ListItemDecorator>
                {m.color === 'danger' ? <Error /> : <InfoOutlined />}
              </ListItemDecorator>

              <ListItemContent>
                <Typography sx={{ fontSize: 'md' }}>{m.title}</Typography>
                <Typography sx={{ fontSize: 'sm' }}>{m.body}</Typography>
              </ListItemContent>
              <Divider orientation="vertical" />
              <Typography sx={{ fontSize: 'sm', maxWidth: 50 }}>
                {spDayjs().from(new Date(m.timestamp))}
              </Typography>
            </ListItem>
          ))}
        </List>
      </ModalDialog>
    </Modal>
  );
};
