import { FormControl, FormHelperText, FormLabel, Option, Select } from '@mui/joy';
import { SyntheticEvent } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate, useParams } from 'react-router';
import { VESTING_CONTRACTS_LIST } from '/src/constants';
import { RouteParams } from '/src/types';

export const VestingPicker = () => {
  const navigate = useNavigate();
  const { address, smctype, root } = useParams<RouteParams>();
  const { t } = useTranslation();

  return (
    <FormControl>
      <FormLabel sx={{ px: 0 }}>{t('vesting.pick-contract')}</FormLabel>
      <Select
        sx={{ py: 2 }}
        size="lg"
        placeholder="..."
        defaultValue={address}
        onChange={(event: SyntheticEvent | null, newValue: string | null) =>
          navigate(`${root ? `/${root}/` : '/'}stats/${smctype || 'vesting'}/${newValue}`, {
            replace: true,
          })
        }
      >
        {Object.keys(VESTING_CONTRACTS_LIST).map((m) => (
          <Option key={`vesting-picker-option-${m}`} value={VESTING_CONTRACTS_LIST[m]}>
            {m}
          </Option>
        ))}
      </Select>
      {!address ? (
        <FormHelperText sx={{ px: 0, color: (t) => t.vars.palette.danger.plainColor }}>
          {t('staking.incorrect-contract')}
        </FormHelperText>
      ) : (
        <FormHelperText sx={{ px: 0, color: (t) => t.vars.palette.danger.plainColor }}>
          {/* {t('staking.do-not-transfer')} */}
        </FormHelperText>
      )}
    </FormControl>
  );
};
