import { atom, DefaultValue, selectorFamily } from 'recoil';
import { STORAGE_WALLET_BALANCES_KEY, TOTAL_BALANCE_REFRESH_DELAY_INTERVAL } from '../constants';
import { getAddress, getSpintriaAddresses } from '../utils';
import { StateStorage } from './effects/utils/state-storage';
import { tonApiClient } from './ton';
import { activeWalletSelector } from './wallets';
import { instanceOfWalletJettonsBalances, WalletJettonsBalances } from '/src/types';

const spintriaMinters = getSpintriaAddresses();

export const jettonsAtom = atom<WalletJettonsBalances | undefined>({
  key: 'jettonsAtom',
  default: undefined,
  effects: [
    ({ setSelf, onSet, trigger, getPromise }) => {
      const storage = new StateStorage<WalletJettonsBalances>(STORAGE_WALLET_BALANCES_KEY);
      const refetchAsync = async (msg = '') => {
        // console.log('jettons.refetch:', msg);
        // await delay(5e3);

        const wallet = await getPromise(activeWalletSelector);
        if (!wallet) return;
        const address = getAddress(wallet.address);
        if (!address) return;
        const data = await tonApiClient.accounts.getAccountJettonsBalances(address);
        const result: WalletJettonsBalances = {
          wallet: wallet.address,
          data: {
            balances: data.balances
              .filter((f) => spintriaMinters.some((s) => f.jetton.address.equals(s!)))
              .sort((a, b) => (a.jetton.symbol === 'SP' ? -1 : 1)),
          },
          timestamp: Date.now(),
        };
        storage.set(result);
        setSelf(result);
      };
      if (trigger === 'get') {
        let value: DefaultValue | WalletJettonsBalances = new DefaultValue();
        getPromise(activeWalletSelector).then((activeWallet) => {
          if (!activeWallet) return;
          const parsedValue = storage.get();
          if (
            instanceOfWalletJettonsBalances(parsedValue) &&
            parsedValue.wallet == activeWallet.address
          ) {
            value = parsedValue;
            // NOTE: 30 seconds
            if (Date.now() > parsedValue.timestamp + 5e3) {
              value.stale = true;
              refetchAsync('is stale');
            }
          } else {
            // NOTE: fetch rates by first get or cache ttl miss
            refetchAsync('first get or cache ttl miss');
          }
          setSelf(value);
        });
      }
      onSet((value, _, isReset) => {
        if (isReset || !instanceOfWalletJettonsBalances(value)) {
          storage.remove();
          // refetchAsync('isReset || !instanceOfWalletJettonsBalances(value)');
        } else {
          storage.set(value);
        }
      });
      const interval = window.setInterval(
        () => refetchAsync('interval'),
        TOTAL_BALANCE_REFRESH_DELAY_INTERVAL,
      );
      return () => {
        typeof interval != 'undefined' && window.clearInterval(interval);
      };
    },
  ],
});

export const jettonSelector = selectorFamily({
  key: 'jettonSelector',
  get:
    (address?: string) =>
    async ({ get }) =>
      address
        ? get(jettonsAtom)?.data.balances.find((f) => f.jetton.address.toRawString() === address)
        : undefined,
});
