import { Address, beginCell, Cell, Contract, ContractProvider } from '@ton/core';

export const Opcodes = {
  withdraw: 0xb5de5f9e,
  terminate: 0x6c95e810,
};

export type DirectVestingData = {
  startTime: number;
  totalDuration: number;
  unlockPeriod: number;
  cliffDuration: number;
  totalDeposited: bigint;
  totalWithdrawals: bigint;
  ownerAddress: Address;
};

export class DirectVestingContract implements Contract {
  constructor(
    readonly address: Address,
    readonly init?: { code: Cell; data: Cell },
  ) {}

  static createFromAddress(address: Address) {
    return new DirectVestingContract(address);
  }

  static withdrawMessage() {
    return beginCell().storeUint(Opcodes.withdraw, 32).storeUint(0, 64).endCell();
  }

  async getVestingData(provider: ContractProvider): Promise<DirectVestingData> {
    const result = await provider.get('get_vesting_data', []);
    return {
      startTime: result.stack.readNumber(),
      totalDuration: result.stack.readNumber(),
      unlockPeriod: result.stack.readNumber(),
      cliffDuration: result.stack.readNumber(),
      totalDeposited: result.stack.readBigNumber(),
      totalWithdrawals: result.stack.readBigNumber(),
      ownerAddress: result.stack.readAddress(),
    };
  }

  async getLockedAmount(provider: ContractProvider, time: number): Promise<bigint> {
    const result = await provider.get('get_locked_amount', [
      {
        type: 'int',
        value: BigInt(time),
      },
    ]);
    return result.stack.readBigNumber();
  }

  static terminateMessage() {
    return beginCell().storeUint(Opcodes.terminate, 32).storeUint(0, 64).endCell();
  }
}
