import {
  Add,
  ArrowDropDown,
  CheckCircle,
  Error,
  KeyboardBackspace,
  Wallet,
} from '@mui/icons-material';
import {
  Alert,
  Avatar,
  Button,
  FormControl,
  FormHelperText,
  FormLabel,
  IconButton,
  Input,
  Stack,
  Typography,
} from '@mui/joy';
import { MessageConsequences } from '@ton-api/client';
import {
  Address,
  beginCell,
  external,
  fromNano,
  internal,
  SendMode,
  storeMessage,
  toNano,
} from '@ton/core';
import { mnemonicNew, mnemonicToPrivateKey } from '@ton/crypto';
import { WalletContractV4 } from '@ton/ton';
import debounce from 'lodash.debounce';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router';
import { useRecoilValue, useSetRecoilState } from 'recoil';
import { StyledCircularProgress } from '../circular-progress';
import { WorkspaceNext } from '../workspace-next';
import { JettonPickerModal } from './jetton-picker-modal';
import {
  DEFAULT_DECIMAL_PLACES,
  FRACTION_DIGITS,
  MAINNET_SPINTRIA_MASTER_ADDRESS,
  NUMBER_COMPACT_TRIGGER_VALUE,
  TON_DECIMAL_PLACES,
  TON_TICKER,
  WORKCHAIN,
} from '/src/constants';
import { JettonWallet } from '/src/contracts';
import { useLoadable } from '/src/hooks';
import { useActiveWallet } from '/src/hooks/useActiveWallet';
import {
  addWalletModalAtom,
  currencyAtom,
  jettonsAtom,
  metricsAtom,
  ratesSelector,
  tonApiClient,
  tonClientSelector,
  walletSelector,
} from '/src/state';
import { appCurrencies, WalletJettonsBalances } from '/src/types';
import { fromUnits, toUnits } from '/src/units';
import { clearInputAmoutValue, delay, getAddress, truncateLong, waitForSeqno } from '/src/utils';

export const SendScreen = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [step, setStep] = useState<'pick-recipient' | 'pick-amount' | 'confirm-tx'>(
    'pick-recipient',
  );
  const setOpenAddWallet = useSetRecoilState(addWalletModalAtom);
  const setMetrics = useSetRecoilState(metricsAtom);
  const client = useLoadable(tonClientSelector);
  const { walletRestored, sender } = useActiveWallet();
  const [sendingTx, setSendingTx] = useState(false);
  const [recipientRaw, setRecipientRaw] = useState('');
  const [recipientPending, setRecipientPending] = useState(false);
  const [recipient, setRecipient] = useState<Address>();
  const [isDnsRecipient, setDnsRecipient] = useState(false);
  const [badRecipient, setBadRecipient] = useState<string>();
  const debouncedSetRecipient = useCallback(
    debounce(
      async (value: string) => {
        if (value.endsWith('.ton')) {
          try {
            const dnsResponse = await tonApiClient.dns.dnsResolve(value);
            if (dnsResponse.wallet?.address) {
              setRecipient(dnsResponse.wallet?.address);
              setDnsRecipient(true);
              setBadRecipient(undefined);
            } else setBadRecipient(t('send.error.recipient-dns'));
          } catch (e) {
            setBadRecipient(t('send.error.dns-404'));
          }
        } else {
          const addr = getAddress(value);
          if (!addr) {
            setBadRecipient(t('send.error.recipient-address'));
          } else if (addr.workChain != WORKCHAIN) {
            setBadRecipient(t('send.error.workchain'));
          } else {
            setRecipient(addr);
          }
        }
        setRecipientPending(false);
      },
      5e2,
      { trailing: true },
    ),
    [],
  );
  // const [commentMessage, setCommentMessage] = useState('');
  const jettons = useLoadable(jettonsAtom);
  const [jetton, setJetton] = useState<WalletJettonsBalances['data']['balances'][number]>();
  const handleChange = useCallback(
    (
      value: string,
      changeValue: string,
      onChange?: (value?: string) => void,
      decimals = FRACTION_DIGITS,
    ) => {
      const inputValue = changeValue.trim();
      const newValue = clearInputAmoutValue(inputValue, decimals);
      const isEmpty = inputValue === '';
      if ((newValue || isEmpty) && newValue !== value) {
        onChange?.(newValue);
      }
    },
    [],
  );
  const [traceOperation, setTraceOperation] = useState<MessageConsequences>();
  const estimateFee = useMemo(
    () => BigInt((traceOperation?.event.extra || 0) * -1),
    [traceOperation],
  );
  const sendHandler = useCallback(async () => {
    if (!client || !walletRestored || !sender || !recipient || !jetton) return;

    const waiter = await waitForSeqno(client, Address.parse(walletRestored.address));
    const decimals = jetton?.jetton.decimals || DEFAULT_DECIMAL_PLACES;
    let senderFail = false;
    setSendingTx(true);

    try {
      await sender?.send({
        to: jetton.walletAddress.address, // current jetton wallet
        // Usually 0.05 TON is enough for most jetton transfers w/o forwardBody
        value: estimateFee,
        body: JettonWallet.transferMessage(
          toUnits(amount, decimals),
          recipient,
          getAddress(walletRestored.address)!,
          null,
          0n,
          null,
        ),
      });
      // const walletKey = await mnemonicToWalletKey(deployerMnemonic.split(" "));
      // const walletContract = WalletContract.create(client, WalletV3R2Source.create({ publicKey: walletKey.publicKey, workchain }));
      // const seqno = await walletContract.getSeqNo();
      // const transfer = walletContract.createTransfer({
      //   secretKey: walletKey.secretKey,
      //   seqno: seqno,
      //   sendMode: SendMode.PAY_GAS_SEPARATLY + SendMode.IGNORE_ERRORS,
      //   order: new InternalMessage({
      //     to: newContractAddress,
      //     value: newContractFunding,
      //     bounce: false,
      //     body: new CommonMessageInfo({
      //       stateInit: new StateInit({ data: initDataCell, code: initCodeCell }),
      //       body: initMessageCell !== null ? new CellMessage(initMessageCell) : null,
      //     }),
      //   }),
      // });
      setMetrics((v) => ({ ...v, sent: { ticker: jetton.jetton.symbol, amount } }));
    } catch (error) {
      senderFail = true;
    }

    if (senderFail) {
      setSendingTx(false);
      return;
    }

    try {
      await waiter();
      await delay(10e3);
    } catch (error) {}

    setSendingTx(false);
  }, [walletRestored, client, sender, recipient, jetton, estimateFee]);
  const currency = useRecoilValue(currencyAtom);
  const spRates = useLoadable(ratesSelector({ address: MAINNET_SPINTRIA_MASTER_ADDRESS }));
  const tonRates = useLoadable(ratesSelector({ address: TON_TICKER }));
  const [amount, setAmount] = useState('');
  const amountByCurrency = useMemo(
    () => (spRates?.prices ? Number(amount || 0) * spRates.prices[currency] : 0),
    [currency, spRates, amount],
  );
  const estimateFeeByCurrency = useMemo(
    () =>
      tonRates?.prices
        ? (estimateFee ? Number(fromUnits(estimateFee, TON_DECIMAL_PLACES)) : 0) *
          tonRates.prices[currency]
        : 0,
    [currency, tonRates, estimateFee],
  );
  const [pendingFee, setPendingFee] = useState(false);
  const [openJettonPickerModal, setOpenJettonPickerModal] = useState(false);
  const accountWallet = useLoadable(walletSelector);
  const pickedJettonBalance = useMemo(
    () => (jetton ? Number(fromUnits(jetton.balance, DEFAULT_DECIMAL_PLACES)) : 0),
    [jetton],
  );

  const emulateTransfer = useCallback(
    debounce(
      async ({
        to,
        responseAddress,
        asset,
        jAmount,
      }: {
        asset: typeof jetton;
        jAmount: string;
        to: Address;
        responseAddress: Address;
      }) => {
        if (!asset) return;
        try {
          // Get wallet's seqno and public key
          const { seqno } = await tonApiClient.wallet.getAccountSeqno(responseAddress);
          const apk = await tonApiClient.accounts.getAccountPublicKey(responseAddress);

          const dummyKey = (await mnemonicToPrivateKey(await mnemonicNew())).secretKey;
          const wallet = WalletContractV4.create({
            workchain: 0,
            publicKey: Buffer.from((apk as any).publicKey, 'hex'),
          });

          const txBody = wallet.createTransfer({
            seqno,
            secretKey: dummyKey,
            sendMode: SendMode.PAY_GAS_SEPARATELY + SendMode.IGNORE_ERRORS,
            messages: [
              internal({
                value: toNano(0.222),
                bounce: true,
                // init: undefined,
                to: asset.walletAddress.address.toString(),
                body: JettonWallet.transferMessage(
                  toUnits(jAmount, asset.jetton.decimals || DEFAULT_DECIMAL_PLACES),
                  to,
                  responseAddress,
                  null,
                  0n,
                  null,
                ),
              }),
            ],
          });
          const emulateTrace = await tonApiClient.emulation.emulateMessageToWallet({
            boc: beginCell()
              .store(
                storeMessage(
                  external({
                    to: responseAddress,
                    init: undefined,
                    body: txBody,
                  }),
                ),
              )
              .endCell(),
          });
          setTraceOperation(emulateTrace);
        } catch (e) {
          console.log('emulate error', e);
        } finally {
          setPendingFee(false);
        }
      },
      5e3,
      { trailing: true },
    ),
    [],
  );

  useEffect(() => {
    if (recipientRaw.trim().length == 0) return;
    setRecipientPending(true);
    setBadRecipient(undefined);
    setRecipient(undefined);
    setAmount('');
    setDnsRecipient(false);
    debouncedSetRecipient(recipientRaw);
  }, [recipientRaw]);

  useEffect(() => {
    setJetton(jettons?.data.balances[0]);
  }, [jettons]);

  useEffect(() => {
    if (!recipient || !walletRestored || !jetton || !amount || step != 'confirm-tx') return;
    setPendingFee(true);
    emulateTransfer({
      jAmount: amount,
      asset: jetton,
      to: recipient,
      responseAddress: getAddress(walletRestored.address)!,
    });
  }, [jetton, recipient, amount, step]);

  return (
    <WorkspaceNext>
      <Stack spacing={2}>
        {!walletRestored ? (
          <Button startDecorator={<Add />} onClick={() => setOpenAddWallet(true)}>
            {t('wallets.add-wallet')}
          </Button>
        ) : (
          <>
            <Typography level="h3">{t('send.title')}</Typography>

            <FormControl
              size="lg"
              color={!!badRecipient ? 'warning' : 'neutral'}
              disabled={step != 'pick-recipient'}
            >
              <FormLabel sx={{ width: '100%', pr: 1 }}>{t('send.recipient')}</FormLabel>
              <Input
                autoFocus
                placeholder={t('send.recipient-placeholder')}
                required
                value={recipientRaw}
                onChange={(e) => setRecipientRaw(e.currentTarget.value)}
                sx={{
                  fontSize: '150%',
                  '--Input-minHeight': '60px',
                  '--Input-placeholderOpacity': 0.3,
                }}
                endDecorator={
                  recipientPending ? (
                    <StyledCircularProgress
                      color="neutral"
                      sx={{
                        '--CircularProgress-size': '20px',
                        '--CircularProgress-trackThickness': '3px',
                        '--CircularProgress-progressThickness': '3px',
                      }}
                    />
                  ) : badRecipient ? (
                    <Error color="inherit" />
                  ) : recipient ? (
                    <CheckCircle color="success" />
                  ) : (
                    <>&nbsp;</>
                  )
                }
              />
              <FormHelperText sx={{ px: 2 }}>
                {isDnsRecipient
                  ? `${t('send.dns-helper')} ${truncateLong(recipient?.toString() || '')}`
                  : badRecipient || <>&nbsp;</>}
              </FormHelperText>
            </FormControl>

            {/* <Typography level="h4">{t('send.comment')}</Typography>
            <FormControl size="lg" color="neutral">
              <Input
                required
                value={commentMessage}
                onChange={(e) => setCommentMessage(e.currentTarget.value)}
                sx={{
                  fontSize: '150%',
                  '--Input-minHeight': '60px',
                  '--Input-placeholderOpacity': 0.3,
                }}
              />
            </FormControl> */}

            {step != 'pick-recipient' && (
              <FormControl
                size="lg"
                disabled={sendingTx || !walletRestored || step == 'confirm-tx'}
              >
                <FormLabel sx={{ width: '100%', pr: 1 }}>
                  <Stack
                    width="100%"
                    direction="row"
                    justifyContent="space-between"
                    alignItems="center"
                    gap={1}
                  >
                    <Typography>{t('send.amount')}</Typography>
                    <Typography
                      textColor="neutral.400"
                      startDecorator={<Wallet sx={{ width: 16, height: 16, color: '#8888' }} />}
                      endDecorator={
                        <Typography sx={{ color: '#8888' }}>{jetton?.jetton.symbol}</Typography>
                      }
                    >
                      {pickedJettonBalance.toLocaleString(undefined, {
                        notation:
                          pickedJettonBalance > NUMBER_COMPACT_TRIGGER_VALUE
                            ? 'compact'
                            : 'standard',
                        maximumFractionDigits: 4,
                      })}
                    </Typography>
                  </Stack>
                </FormLabel>
                <Input
                  placeholder="0.00"
                  autoFocus
                  required
                  endDecorator={
                    <Button
                      variant="plain"
                      size="lg"
                      onClick={() => setOpenJettonPickerModal(true)}
                      sx={{
                        p: 1,
                        color: (t) => t.palette.neutral[t.palette.mode == 'dark' ? 600 : 400],
                        '&:hover': {
                          background: 'none',
                          color: (t) => t.palette.text.primary,
                        },
                      }}
                      endDecorator={
                        <Stack direction="row" alignItems="center" gap={0.25}>
                          <Avatar src={jetton?.jetton.image} sx={{ width: 32, height: 32 }} />
                          <ArrowDropDown sx={{ color: 'inherit' }} />
                        </Stack>
                      }
                    >
                      {jetton?.jetton.symbol}
                    </Button>
                  }
                  value={amount}
                  onChange={(e) =>
                    handleChange(
                      amount,
                      e.currentTarget.value,
                      (value = '') => {
                        const decimals = jetton?.jetton.decimals || DEFAULT_DECIMAL_PLACES;
                        const bigV = toUnits(value || '', decimals);
                        const realBalance = BigInt(jetton?.balance || 0n);
                        const amount =
                          bigV > realBalance ? fromUnits(realBalance, decimals) : value;
                        setAmount(amount);
                        if (Number(amount) > 0) {
                          // throttledSimulateSend({
                          //   askUnits: toUnits(amount, DEFAULT_DECIMAL_PLACES).toString(),
                          // });
                        }
                      },
                      jetton?.jetton.decimals || DEFAULT_DECIMAL_PLACES,
                    )
                  }
                  sx={{
                    fontSize: '150%',
                    '--Input-minHeight': '60px',
                    '--Input-placeholderOpacity': 0.3,
                  }}
                />
                <FormHelperText
                  sx={{
                    px: 2,
                    display: 'flex',
                    flexDirection: 'row',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    gap: 1,
                  }}
                >
                  <Typography>
                    {appCurrencies[currency].symbol}
                    {amountByCurrency.toLocaleString(undefined, {
                      notation:
                        amountByCurrency > NUMBER_COMPACT_TRIGGER_VALUE ? 'compact' : 'standard',
                      maximumFractionDigits: 2,
                    })}
                  </Typography>
                  {pendingFee ? (
                    <StyledCircularProgress
                      color="neutral"
                      sx={{
                        '--CircularProgress-size': '20px',
                        '--CircularProgress-trackThickness': '3px',
                        '--CircularProgress-progressThickness': '3px',
                      }}
                    />
                  ) : (
                    !!estimateFeeByCurrency && (
                      <Stack direction="column" alignItems="end">
                        <Typography>
                          <Typography sx={{ color: '#8888' }}>Fee ~</Typography>{' '}
                          {fromUnits(estimateFee, TON_DECIMAL_PLACES)} TON
                        </Typography>
                        <Typography>
                          {appCurrencies[currency].symbol}{' '}
                          {estimateFeeByCurrency.toLocaleString(undefined, {
                            notation: 'compact',
                            maximumFractionDigits: 2,
                          })}
                        </Typography>
                      </Stack>
                    )
                  )}
                </FormHelperText>
              </FormControl>
            )}
            {accountWallet && accountWallet.balance < toNano(0.2) ? (
              <Alert color="warning" variant="soft">
                {t('send.not-enough-ton', { balance: fromNano(accountWallet?.balance || 0n) })}
              </Alert>
            ) : (
              <></>
            )}

            <Stack direction="row" width="100%" gap={2}>
              <IconButton
                disabled={sendingTx}
                size="lg"
                type="submit"
                onClick={() =>
                  step == 'pick-recipient' ? navigate(-1) : setStep('pick-recipient')
                }
              >
                <KeyboardBackspace />
              </IconButton>
              {step == 'pick-recipient' ? (
                <Button
                  disabled={recipientPending || !!badRecipient || !recipient}
                  fullWidth
                  size="lg"
                  type="submit"
                  onClick={() => setStep('pick-amount')}
                >
                  {t('send.next')}
                </Button>
              ) : (
                <Button
                  fullWidth
                  size="lg"
                  type="submit"
                  loading={sendingTx || pendingFee}
                  disabled={
                    !client ||
                    !walletRestored ||
                    Number(amount || 0) <= 0 ||
                    !amountByCurrency ||
                    !amount ||
                    !accountWallet ||
                    accountWallet.balance < toNano(0.2) ||
                    (step == 'confirm-tx' && estimateFee == 0n)
                  }
                  onClick={() => (step == 'confirm-tx' ? sendHandler() : setStep('confirm-tx'))}
                >
                  {t(step == 'confirm-tx' ? 'send.send' : 'send.confirm')}
                </Button>
              )}
            </Stack>
          </>
        )}
      </Stack>
      <JettonPickerModal
        open={openJettonPickerModal}
        balances={jettons?.data.balances}
        onClose={() => setOpenJettonPickerModal(false)}
        onSelect={(v) => {
          setAmount('');
          setJetton(v);
          setOpenJettonPickerModal(false);
        }}
      />
    </WorkspaceNext>
  );
};
