import { atom, DefaultValue, selectorFamily } from 'recoil';
import { ASSETS_REFRESH_DELAY_INTERVAL, STORAGE_ASSETS_KEY } from '../constants';
import { fetchAssetByAddress, fetchAssets, getAddress } from '../utils';
import { StateStorage } from './effects/utils/state-storage';
import { tonClientSelector } from './ton';
import { WalletEventManager } from './wallet-event-manager';
import {
  Asset,
  instanceOfAssetArray,
  isWalletEventDetail,
  WalletEventDetail,
  WalletEventType,
} from '/src/types';

export const assetsAtom = atom<Asset[]>({
  key: 'assetsAtom',
  default: [],
  effects: [
    ({ setSelf, onSet, trigger, getPromise }) => {
      const storage = new StateStorage<Asset[]>(STORAGE_ASSETS_KEY);
      const refetchAssets = async () => {
        const tonClient = await getPromise(tonClientSelector);
        const assets = await fetchAssets(tonClient);
        storage.set(assets);
        setSelf(assets);
      };
      const refetchAssetAsync = async (e: CustomEvent<WalletEventDetail>) => {
        // console.log('refetchAssetAsync', e.detail);
        if (!isWalletEventDetail(e.detail)) {
          return;
        }
        const { address, smcType } = e.detail;

        const minter = getAddress(address);
        if (!minter) return;

        const tonClient = await getPromise(tonClientSelector);
        const asset = await fetchAssetByAddress(tonClient, smcType, address);
        if (!asset) return;

        const storageAssets = storage.get();
        if (!instanceOfAssetArray(storageAssets)) return;

        const assets = [
          ...storageAssets?.filter((f) => !getAddress(f.address)?.equals(minter)),
          asset,
        ];
        storage.set(assets);
        setSelf(assets);
      };
      const refetchAssetSync = ((e: CustomEvent<WalletEventDetail>) => {
        if (!isWalletEventDetail(e.detail)) {
          return;
        }
        refetchAssetAsync(e);
      }) as EventListener;

      if (trigger === 'get') {
        let value: DefaultValue | Asset[] = new DefaultValue();
        try {
          const parsedValue = storage.get();
          if (instanceOfAssetArray(parsedValue)) {
            value = parsedValue;
          } else {
            // NOTE: fetch assets by first get
            refetchAssets();
          }
        } catch (err) {
          console.info(`Can't JSON.parse value from`, STORAGE_ASSETS_KEY);
          storage.remove();
        }
        setSelf(value);
      }

      // NOTE: fetch assets by interval
      window.setInterval(refetchAssets, ASSETS_REFRESH_DELAY_INTERVAL);

      // NOTE: subscribe to event
      WalletEventManager.subscribe(WalletEventType.RefetchAssets, refetchAssetSync);

      onSet((value, _, isReset) => {
        if (isReset || !instanceOfAssetArray(value)) {
          storage.remove();
        } else {
          storage.set(value);
        }
      });
      return () => {
        WalletEventManager.unsubscribe(WalletEventType.RefetchAssets, refetchAssetSync);
      };
    },
  ],
});

export const assetsSelector = selectorFamily({
  key: 'assetsSelector',
  get:
    (address?: string) =>
    async ({ get }) =>
      address ? get(assetsAtom)?.find((f) => f.address === address) : undefined,
});
