import { atom, selector } from 'recoil';
import { localStorageEffect, tmaSecureStorageEffect } from '../effects';
import { STORAGE_WALLETS_KEY } from '/src/constants';
import { isWalletItems, WalletItem } from '/src/types';

export type BiometryWallets = {
  version: number;
  mnemonics: string[];
};
export type BiometryWalletsMin = {
  v: BiometryWallets['version'];
  ms: BiometryWallets['mnemonics'];
};

export function isBiometryWalletsMin(o: any): o is BiometryWalletsMin {
  return o && 'v' in o && typeof o.v == 'number' && 'ms' in o && Array.isArray(o.ms);
}

/**
 * @description current version has limits to store 4 wallets records
 * Possible way to store 5 records is use padEnd with word as with known word
 * max length 8 symbols, sample:
 * @example
 * JSON.stringify([1, Array(5).fill(0).map(m => Array(24)
 *     .fill(0)
 *     .map(m =>
 *        Math
 *        .random()
 *        .toString(36)
 *        .substring(2, 2 + Math.round(3 + Math.random() * 5))
 *        .padEnd(8,'*'))
 *     .join('')
 *   )
 * ]).length
 * @description should return alway fixed length 980
 */
export const secureStorageState = atom({
  key: 'secureStorageState',
  default: undefined,
  effects: [
    tmaSecureStorageEffect<BiometryWalletsMin | undefined>({
      isValid: isBiometryWalletsMin,
    }),
  ],
});

export const walletsAtom = atom({
  key: 'walletsAtom',
  default: [],
  effects: [
    localStorageEffect<WalletItem[]>({
      key: STORAGE_WALLETS_KEY,
      isValid: isWalletItems,
    }),
  ],
});

export const activeWalletSelector = selector({
  key: 'activeWalletSelector',
  get: async ({ get }) => get(walletsAtom)?.find((f) => f.active),
});
