import {
  Avatar,
  Chip,
  List,
  ListItem,
  ListItemButton,
  ListItemContent,
  ListItemDecorator,
  Sheet,
  Skeleton,
  Stack,
  Typography,
} from '@mui/joy';
import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate, useParams } from 'react-router';
import { useRecoilValue, useRecoilValueLoadable } from 'recoil';
import {
  MAINNET_SPINTRIA_MASTER_ADDRESS,
  NUMBER_COMPACT_TRIGGER_VALUE,
  STALE_OPACITY,
} from '/src/constants';
import {
  currencyAtom,
  directVestingSelector,
  jettonsAtom,
  ratesSelector,
  vestingContractAddressSelector,
  zeroJettonsAtom,
} from '/src/state';
import { appCurrencies, RouteParams } from '/src/types';
import { fromUnits } from '/src/units';

export const JettonsList = () => {
  const navigate = useNavigate();
  const { t } = useTranslation();
  const { root } = useParams<RouteParams>();
  const vestingContractAddress = useRecoilValueLoadable(vestingContractAddressSelector);
  const vesting = useRecoilValueLoadable(directVestingSelector);
  const showZeroJettons = useRecoilValue(zeroJettonsAtom);
  const rates = useRecoilValueLoadable(ratesSelector({ address: MAINNET_SPINTRIA_MASTER_ADDRESS }));
  const currency = useRecoilValue(currencyAtom);
  const jettons = useRecoilValueLoadable(jettonsAtom);
  const rate = useMemo(
    () =>
      rates.state === 'hasValue' &&
      rates.contents &&
      rates.contents.prices &&
      rates.contents.prices[currency]
        ? rates.contents.prices[currency]
        : 0,
    [rates, currency],
  );
  const list = useMemo(() => {
    switch (jettons.state) {
      case 'hasValue':
        const list = jettons.contents?.data.balances;
        const filtered = showZeroJettons ? list : list?.filter((f) => Number(f.balance) > 0);
        return filtered?.map((m, i) => {
          const jBalance = Number(fromUnits(m.balance, m.jetton.decimals));
          const disabled =
            jettons.contents?.stale ||
            m.jetton.address.toRawString() === MAINNET_SPINTRIA_MASTER_ADDRESS;
          return (
            <ListItem
              variant="soft"
              key={`jetton-item-${i}`}
              sx={[jettons.contents?.stale ? { opacity: STALE_OPACITY } : {}]}
              className={jettons.contents?.stale ? '' : 'fade-out'}
            >
              <ListItemButton
                disabled={disabled}
                onClick={() =>
                  navigate(`${root ? `/${root}/` : '/'}jetton/${m.jetton.address.toRawString()}`)
                }
              >
                <ListItemDecorator>
                  <Avatar src={m.jetton.image} />
                </ListItemDecorator>
                <ListItemContent>
                  <Typography level="title-md">{m.jetton.symbol}</Typography>
                  <Typography level="body-sm" sx={{ color: '#888c' }} noWrap>
                    {m.jetton.name}
                  </Typography>
                </ListItemContent>
                <Stack direction="column" alignItems="end">
                  <Typography level="title-md" noWrap endDecorator={m.jetton.symbol}>
                    {jBalance.toLocaleString(undefined, {
                      notation: 'compact',
                      maximumFractionDigits: 2,
                    })}
                  </Typography>
                  <Typography
                    level="body-sm"
                    sx={{ color: '#888c' }}
                    noWrap
                    endDecorator={appCurrencies[currency].symbol}
                  >
                    {(rate * jBalance).toLocaleString(undefined, {
                      notation: 'compact',
                      maximumFractionDigits: 2,
                    })}
                  </Typography>
                </Stack>
              </ListItemButton>
            </ListItem>
          );
        });

      case 'loading':
        return <SkeletonJettonListItems />;

      default:
        return null;
    }
  }, [jettons, rate, showZeroJettons]);
  const directVestingListItem = useMemo(() => {
    if (!vestingContractAddress) {
      return <SkeletonVestingItem />;
    }
    // if (vesting.state !== 'hasValue' || !vesting.contents) {
    //   if (!!vestingContractAddress) {
    //     return <SkeletonVestingItem />;
    //   }
    //   return;
    // }
    const toWithdraw =
      vesting.state == 'hasValue' && vesting.contents?.data
        ? vesting.contents.data.totalDeposited - vesting.contents.data.totalWithdrawals
        : 0n;
    const vBalance = toWithdraw > 0n ? Number(fromUnits(toWithdraw, 8)) : 0;

    return (
      <ListItem variant="soft">
        <ListItemButton
          onClick={() => navigate(`${root ? `/${root}/` : '/'}jetton/${vesting.contents?.address}`)}
        >
          <ListItemDecorator>
            <Avatar src="/spintria-white.png" />
          </ListItemDecorator>
          <ListItemContent>
            <Typography level="title-md">{t('vSP')}</Typography>
            <Typography level="body-sm" sx={{ color: '#888c' }} noWrap>
              {t('Direct Vesting Contract')}
            </Typography>
          </ListItemContent>
          <Stack direction="column" alignItems="end">
            {vesting.state == 'hasValue' ? (
              <Typography level="title-md" noWrap endDecorator={'vSP'}>
                {typeof vBalance === 'number'
                  ? vBalance.toLocaleString(undefined, {
                      notation: 'compact',
                      maximumFractionDigits: 2,
                    })
                  : '•••'}
              </Typography>
            ) : (
              '...'
            )}
            {vesting.state == 'hasValue' ? (
              <Typography
                level="body-sm"
                sx={{ color: '#888c' }}
                noWrap
                endDecorator={appCurrencies[currency].symbol}
              >
                {typeof vBalance === 'number'
                  ? (rate * vBalance).toLocaleString(undefined, {
                      notation:
                        rate * vBalance > NUMBER_COMPACT_TRIGGER_VALUE ? 'compact' : 'standard',
                      maximumFractionDigits: 2,
                    })
                  : '•••'}
              </Typography>
            ) : (
              '...'
            )}
          </Stack>
        </ListItemButton>
      </ListItem>
    );
  }, [vesting, vestingContractAddress]);
  const directVestingSimpleItem = useMemo(() => {
    if (!vestingContractAddress) {
      return <SkeletonVestingItem />;
    }

    return (
      <ListItem variant="soft">
        <ListItemButton
          onClick={() =>
            navigate(`${root ? `/${root}/` : '/'}vesting/${vesting.contents?.address}`)
          }
        >
          <ListItemDecorator>
            <Avatar src="/spintria-white.png" />
          </ListItemDecorator>
          <ListItemContent>
            <Typography level="title-md">{t('vSP')}</Typography>
            <Typography level="body-sm" sx={{ color: '#888c' }} noWrap>
              {t('Direct Vesting Contract')}
            </Typography>
          </ListItemContent>
          <Stack direction="column" alignItems="end">
            <Chip color="danger">Withdraw only</Chip>
          </Stack>
        </ListItemButton>
      </ListItem>
    );
  }, [vesting, vestingContractAddress]);

  return (
    <Sheet variant="plain" sx={{ background: 'none', overflow: 'auto', borderRadius: 'sm' }}>
      <List sx={{ p: 0, '--List-gap': '12px', '--ListItemDecorator-size': '56px' }}>
        {directVestingSimpleItem}
        {directVestingListItem}
        {list}
      </List>
    </Sheet>
  );
};

const SkeletonJettonListItems = () =>
  Array(4)
    .fill(0)
    .map((m, i) => <SkeletonJettonListItem key={`skeleton-item-${i}`} />);

const SkeletonJettonListItem = () => (
  <ListItem sx={{ opacity: 0.25 }}>
    <ListItemButton disabled>
      <ListItemDecorator>
        <Skeleton animation="wave" variant="circular" width={40} height={40} />
      </ListItemDecorator>
      <ListItemContent>
        <Typography level="title-md">
          <Skeleton animation="wave">{'symb'}</Skeleton>
        </Typography>
        <Typography level="body-sm" sx={{ color: '#888c' }} noWrap>
          <Skeleton animation="wave">{'jetton.name'}</Skeleton>
        </Typography>
      </ListItemContent>
      <Stack direction="column" alignItems="end">
        <Typography level="title-md" noWrap>
          <Skeleton animation="wave">0000</Skeleton>
        </Typography>
        <Typography level="body-sm" sx={{ color: '#888c' }} noWrap>
          <Skeleton animation="wave">00</Skeleton>
        </Typography>
      </Stack>
    </ListItemButton>
  </ListItem>
);

const SkeletonVestingItem = () => {
  const { t } = useTranslation();
  return (
    <ListItem sx={{ opacity: 0.25 }}>
      <ListItemButton disabled>
        <ListItemDecorator>
          <Avatar src="/spintria-white.png" />
        </ListItemDecorator>
        <ListItemContent>
          <Typography level="title-md">{t('vSP')}</Typography>
          <Typography level="body-sm" sx={{ color: '#888c' }} noWrap>
            {t('Direct Vesting Contract')}
          </Typography>
        </ListItemContent>
        <Stack direction="column" alignItems="end">
          <Typography level="title-md" noWrap>
            <Skeleton animation="wave">0000</Skeleton>
          </Typography>
          <Typography level="body-sm" sx={{ color: '#888c' }} noWrap>
            <Skeleton animation="wave">00</Skeleton>
          </Typography>
        </Stack>
      </ListItemButton>
    </ListItem>
  );
};
