import { Check, InfoOutlined } from '@mui/icons-material';
import {
  Button,
  Card,
  CardContent,
  DialogContent,
  DialogTitle,
  FormControl,
  FormLabel,
  IconButton,
  Input,
  Modal,
  ModalDialog,
  Skeleton,
  Stack,
  Tooltip,
  Typography,
} from '@mui/joy';
import { FormEvent, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { DEFAULT_DECIMAL_PLACES } from '/src/constants';
import { usePrimaryWallet, useProvideRewardPool } from '/src/hooks';
import { Asset } from '/src/types';
import { fromUnits, toUnits } from '/src/units';

type Props = {
  open: boolean;
  setOpen: (v: boolean) => void;
  data?: Asset;
  loading: boolean;
};

export const ModalProvideRewardPoolForm = ({ data, open, setOpen, loading }: Props) => {
  const { t } = useTranslation();
  const { friendlyBalance, jetton, spintria } = usePrimaryWallet();
  const { amount, closeForm, setAmount, sendingTx, sendProvideRewardPoolAction } =
    useProvideRewardPool(jetton.data);
  const decimals = DEFAULT_DECIMAL_PLACES;
  const rewardPool = useMemo(
    () => Number(fromUnits(data?.staking?.reward_pool || 0n, DEFAULT_DECIMAL_PLACES)),
    [data],
  );
  const minimumRewardPool = useMemo(() => {
    if (!data?.staking || !data?.value.totalSupply) return 0;

    return Number(
      fromUnits(
        ((data.value.totalSupply * data.staking.fixed_apy) / 100n / 365n) *
          BigInt(data.staking.lockup || 30),
        8,
      ),
    );
  }, [data]);

  return (
    <Modal open={open} onClose={() => setOpen(false)}>
      <ModalDialog
        sx={(theme) => ({
          [theme.breakpoints.only('xs')]: {
            top: 0,
            bottom: 'unset',
            left: 0,
            right: 0,
            borderRadius: 0,
            transform: 'none',
            maxWidth: 'unset',
          },
        })}
      >
        <DialogTitle>{t('staking.form.title-reward')}</DialogTitle>
        <DialogContent>{t('staking.form.description-reward')}</DialogContent>
        <form
          onSubmit={(event: FormEvent<HTMLFormElement>) => {
            event.preventDefault();
            setOpen(false);
          }}
        >
          <Stack spacing={2}>
            <FormControl size="lg">
              <FormLabel sx={{ width: '100%' }}>
                <Stack
                  width="100%"
                  direction="row"
                  justifyContent="space-between"
                  alignItems="center"
                  gap={1}
                >
                  <Typography>{t('staking.form.amount')}</Typography>
                  <Stack direction="row" gap={1}>
                    <Typography
                      textColor="neutral.400"
                      sx={{ position: 'relative', overflow: 'hidden' }}
                    >
                      <Skeleton loading={loading}>
                        {t('staking.form.balance')}:{' '}
                        {(friendlyBalance - Number(amount)).toLocaleString()}
                      </Skeleton>
                    </Typography>
                    <Button
                      disabled={
                        loading ||
                        closeForm ||
                        sendingTx ||
                        !friendlyBalance ||
                        friendlyBalance === 0
                      }
                      variant="soft"
                      sx={{ py: 0.1, px: 1, minHeight: 25 }}
                      onClick={() => setAmount(friendlyBalance.toString())}
                    >
                      {t('staking.form.button-max')}
                    </Button>
                  </Stack>
                </Stack>
              </FormLabel>
              <Input
                disabled={
                  loading || closeForm || sendingTx || !friendlyBalance || friendlyBalance === 0
                }
                autoFocus
                required
                endDecorator={spintria?.value.content?.symbol}
                value={amount}
                onChange={(e) => {
                  const value = Number(e.currentTarget.value).toFixed();
                  const bigV = toUnits(value, decimals);
                  const realBalance = jetton?.data?.balance.value || 0n;
                  setAmount(bigV > realBalance ? friendlyBalance.toString() : value);
                }}
              />
            </FormControl>
            <Card variant="soft" sx={{ width: '100%' }}>
              <CardContent sx={{ textAlign: 'center' }}>
                <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
                  <Tooltip title={t('staking.form.apy-info')} variant="solid">
                    <Typography
                      endDecorator={
                        <InfoOutlined color="secondary" sx={{ width: 18, height: 18 }} />
                      }
                    >
                      {t('staking.form.apy')}
                    </Typography>
                  </Tooltip>
                  <Typography sx={{ position: 'relative', overflow: 'hidden' }}>
                    <Skeleton loading={loading}>
                      {data?.staking?.fixed_apy.toLocaleString()}%
                    </Skeleton>
                  </Typography>
                </Stack>
                <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
                  <Typography>{t('staking.form.est-reward')}</Typography>
                  <Typography sx={{ position: 'relative', overflow: 'hidden' }}>
                    <Skeleton loading={loading}>
                      {Number((minimumRewardPool || 0) - rewardPool).toLocaleString()}
                    </Skeleton>
                  </Typography>
                </Stack>
              </CardContent>
            </Card>
            {closeForm ? (
              <IconButton color="success" onClick={() => setOpen(false)}>
                <Check />
              </IconButton>
            ) : (
              <Button
                size="lg"
                type="submit"
                loading={sendingTx}
                disabled={
                  loading ||
                  closeForm ||
                  !data ||
                  !data.staking ||
                  !friendlyBalance ||
                  friendlyBalance === 0 ||
                  !amount ||
                  !Number(amount)
                  // toUnits(amount, decimals) > data.staking?.max_stake
                }
                onClick={() => sendProvideRewardPoolAction()}
              >
                {t('staking.form.button-stake')}
              </Button>
            )}
          </Stack>
        </form>
      </ModalDialog>
    </Modal>
  );
};
