import { postEvent, retrieveLaunchParams } from '@telegram-apps/sdk-react';

import { PropsWithChildren, useEffect } from 'react';
import { HashRouter } from 'react-router-dom';
import { useSetRecoilState } from 'recoil';
import { metricsAtom } from '../state';

export const TelegramRouter = ({ children }: PropsWithChildren) => {
  const setMetrics = useSetRecoilState(metricsAtom);

  useEffect(() => {
    const lp = retrieveLaunchParams();
    if (['macos', 'tdesktop', 'weba', 'web', 'webk'].indexOf(lp.tgWebAppPlatform) === -1) {
      postEvent('web_app_expand'); // Expand the application
      document.body.classList.add('mobile-body');
      document.getElementById('root')?.classList.add('mobile-wrap');
    }
    const deeplink = lp.tgWebAppStartParam ? `tma-${lp.tgWebAppStartParam}` : 'tma-direct';
    setMetrics((v) => ({ ...v, deeplink, user: lp.tgWebAppData?.user?.id.toString() }));
  }, []);

  return <HashRouter>{children}</HashRouter>;
};
