import { useEffect } from 'react';
import { STORAGE_RESET_TONCONNECT_KEY } from '../constants';

export function useResetTonconnectBug() {
  useEffect(() => {
    const isResetedBefore = window.localStorage.getItem(STORAGE_RESET_TONCONNECT_KEY);
    if (isResetedBefore) return;
    Object.keys(window.localStorage)
      .filter((f) => f.indexOf('ton-connect') === 0)
      .forEach((f) => window.localStorage.removeItem(f));
    window.localStorage.setItem(STORAGE_RESET_TONCONNECT_KEY, Date.now().toString());
  }, []);
}
