import { CheckCircle } from '@mui/icons-material';
import {
  Alert,
  Box,
  Button,
  DialogActions,
  Divider,
  FormControl,
  FormLabel,
  Input,
  Modal,
  ModalClose,
  ModalDialog,
  Stack,
  Typography,
} from '@mui/joy';
import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { StyledCircularProgress } from '../circular-progress';
import { useWalletModal } from './useWalletModal';
import { delay } from '/src/utils';

type Props = {
  open: boolean;
  onClose: (v: boolean) => void;
  onBack: () => void;
};

export const GenerateWalletModal = ({ open, onClose, onBack }: Props) => {
  const { t } = useTranslation();
  const [ready, setReady] = useState(false);
  const {
    finishAddOrImport,
    walletName,
    setWalletName,
    generating,
    generatePhrase,
    retryMessage,
    isAuthenticated,
    authenticating,
    isAccessGranted,
    authenticateStorage,
  } = useWalletModal('generate');

  useEffect(() => {
    (async () => {
      await generatePhrase();
      await delay(3e2);
      setReady(true);
    })();
  }, []);

  useEffect(() => {
    if (isAccessGranted && !isAuthenticated) {
      authenticateStorage();
    }
  }, [isAccessGranted, isAuthenticated, authenticateStorage]);

  return (
    <Modal open={open} onClose={() => onBack()}>
      <ModalDialog>
        <ModalClose />
        <Typography level="h3">{t('wallets.new-wallet')}</Typography>
        <Typography level="body-md">{t('wallets.create-wallet')}</Typography>
        <Divider />
        <Stack
          direction="column"
          alignItems="center"
          justifyContent="center"
          minHeight={250}
          gap={2}
          width={'100%'}
        >
          {ready ? (
            <Box maxWidth={150} textAlign="center">
              <CheckCircle color="success" sx={{ width: 128, height: 128 }} />
              <Typography>{t('wallets.wallet-created')}</Typography>
            </Box>
          ) : (
            generating && (
              <>
                <StyledCircularProgress thickness={3} />
                <Typography>{t('wallets.generating-wallet')}</Typography>
              </>
            )
          )}
        </Stack>

        <form
          id="new-wallet-form"
          name="new-wallet-form"
          onSubmit={(e) => {
            e.preventDefault();
            finishAddOrImport(onClose);
          }}
        >
          <FormControl disabled={generating || !ready}>
            <FormLabel>{t('wallets.wallet-name-label')}</FormLabel>
            <Input
              autoFocus
              required
              value={walletName}
              onChange={(e) => setWalletName(e.currentTarget.value)}
              type="text"
              name="username"
              autoComplete="username"
            />
          </FormControl>
          {/* <input
            id="new-phrase"
            type="password"
            name="new-phrase"
            value={phrase.join(',')}
            autoComplete="new-password"
            style={{ display: 'none' }}
            onChange={() => {}}
          /> */}
        </form>
        {retryMessage && (
          <Alert color="danger" variant="soft">
            {retryMessage}
          </Alert>
        )}
        <DialogActions>
          {isAuthenticated ? (
            <Button
              variant="solid"
              color="primary"
              disabled={generating || !ready || walletName.trim().length == 0}
              type="submit"
              form="new-wallet-form"
            >
              Continue
            </Button>
          ) : isAccessGranted ? (
            <Button
              loading={authenticating}
              variant="solid"
              color="primary"
              onClick={() => authenticateStorage()}
            >
              {t('Authenticate')}
            </Button>
          ) : (
            <></>
          )}
          <Button variant="plain" color="neutral" onClick={() => onBack()}>
            Back
          </Button>
        </DialogActions>
      </ModalDialog>
    </Modal>
  );
};
