import { selector } from 'recoil';
import { getAddress } from '../utils';
import { tonApiClient } from './ton';
import { activeWalletSelector } from './wallets';

export const walletSelector = selector({
  key: 'walletSelector',
  get: async ({ get }) => {
    const wallet = get(activeWalletSelector);
    if (!wallet) return;
    const address = getAddress(wallet.address);
    if (!address) return;
    return tonApiClient.accounts.getAccount(address);
  },
});
