import { TonClient } from '@ton/ton';
import { RateLimiter } from './rate-limiter';

// Инициализируем лимитер: 1 RPS для бесплатного тарифа, 3 попытки ретрая
const tonCenterRateLimiter = new RateLimiter(1, 1250, 3);

// Перехватываем оригинальный fetch браузера
const originalFetch = window.fetch;

window.fetch = async function (input, init) {
  const url = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;

  // Перехватываем только запросы, идущие на домен toncenter
  if (url.includes('toncenter.com')) {
    return tonCenterRateLimiter.schedule(async () => {
      try {
        const response = await originalFetch(input, init);

        // Если поймали лимит 429 — прокидываем статус для логики ретрая в RateLimiter
        if (response.status === 429) {
          const error = new Error('TonCenter Rate Limit Exceeded (429)') as any;
          error.status = 429;
          throw error;
        }

        return response;
      } catch (error: any) {
        if (error?.status !== 429 && error?.response?.status === 429) {
          error.status = 429;
        }
        throw error;
      }
    });
  }

  // Все остальные запросы приложения (например, к TonAPI или вашему бэкенду) пропускаем без изменений
  return originalFetch(input, init);
};

// 3. Чистая инициализация клиента — TS теперь полностью доволен!
export const tonCenterClient = new TonClient({
  endpoint: 'https://toncenter.com/api/v2/jsonRPC',
  apiKey: 'ce70dceffcf6f10b37f46d7ff0f5e767899b07c5bf54c83aa638fea0f714a4a7',
});

