import { Check } from '@mui/icons-material';
import { Button, DialogTitle, IconButton, Modal, ModalDialog, Stack } from '@mui/joy';
import { FormEvent, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { useWithdrawUnlocked } from '/src/hooks';

type Props = {
  open: boolean;
  setOpen: (v: boolean) => void;
  data?: bigint | undefined;
  loading: boolean;
};

export const ModalClaimForm = ({ open, setOpen, data, loading }: Props) => {
  const { t } = useTranslation();
  const { closeForm, sendingTx, sendWithdraw } = useWithdrawUnlocked();
  const hasBalance = useMemo(() => data && data > 0n, [data]);

  return (
    <Modal open={open} onClose={() => setOpen(false)}>
      <ModalDialog
        sx={(theme) => ({
          [theme.breakpoints.only('xs')]: {
            top: 0,
            bottom: 'unset',
            left: 0,
            right: 0,
            borderRadius: 0,
            transform: 'none',
            maxWidth: 'unset',
          },
        })}
      >
        <DialogTitle>{t('vesting.form.title-claim')}</DialogTitle>
        <form
          onSubmit={(event: FormEvent<HTMLFormElement>) => {
            event.preventDefault();
            setOpen(false);
          }}
        >
          <Stack spacing={2}>
            {closeForm ? (
              <IconButton color="success" onClick={() => setOpen(false)}>
                <Check />
              </IconButton>
            ) : (
              <Button
                size="lg"
                type="submit"
                loading={sendingTx}
                disabled={loading || closeForm || !data || !hasBalance}
                onClick={() => sendWithdraw()}
              >
                {t('vesting.form.button-withdraw')}
              </Button>
            )}
          </Stack>
        </form>
      </ModalDialog>
    </Modal>
  );
};
