import {
  Box,
  Button,
  Card,
  CardContent,
  Divider,
  LinearProgress,
  Skeleton,
  Stack,
  Typography,
} from '@mui/joy';
import { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useRecoilValueLoadable } from 'recoil';
import { BodyTitle } from './body-title';
import { ModalDirectClaimForm } from './modal-direct-claim-form';
import { DEFAULT_DECIMAL_PLACES, NOW, START_TIME_FORMAT } from '/src/constants';
import { useActiveWallet } from '/src/hooks';
import { spDayjs } from '/src/libs';
import { directVestingSelector } from '/src/state';
import { fromUnits } from '/src/units';

export const DirectVestingInfo = () => {
  const { t, i18n } = useTranslation();
  const { walletRestored } = useActiveWallet();
  const vesting = useRecoilValueLoadable(directVestingSelector);
  const [openClaimForm, setOpenClaimForm] = useState(false);
  const info = useMemo(() => {
    if (vesting.state !== 'hasValue' || !vesting.contents) {
      return;
    }
    const decimals = DEFAULT_DECIMAL_PLACES;
    const {
      data: { startTime, unlockPeriod, totalDuration, totalDeposited, totalWithdrawals },
      locked,
    } = vesting.contents;
    const diff = NOW() - startTime;
    const periods = totalDuration / unlockPeriod;
    let currentPeriod = Math.floor(diff / unlockPeriod);
    if (currentPeriod < 0) {
      currentPeriod = 0;
    }
    const nextPeriod = startTime + (currentPeriod + 1) * unlockPeriod;
    const currentPercent = Number(((100 / periods) * currentPeriod).toFixed());
    return {
      currentPeriod,
      currentPercent: currentPercent < 100 ? currentPercent : 100,
      nextPeriod,
      balance: Number(
        fromUnits(
          vesting.contents.data.totalDeposited - vesting.contents.data.totalWithdrawals,
          decimals,
        ),
      ),
      estUnlocked:
        totalDeposited - totalWithdrawals > 0
          ? fromUnits(totalDeposited - totalWithdrawals - locked, decimals)
          : 0,
      isFinished: startTime + totalDuration < nextPeriod,
      periods,
    };
  }, [vesting]);

  return (
    <Box>
      <BodyTitle />
      <Card variant="outlined" sx={{ width: '100%', boxShadow: 'none', border: 0 }}>
        <CardContent sx={{ textAlign: 'center' }}>
          <Typography level="h2">
            {vesting.state == 'hasValue'
              ? spDayjs((vesting.contents?.data?.startTime || 0) * 1000).format(START_TIME_FORMAT)
              : '...'}
          </Typography>
          <Typography level="body-md">{t('vesting.startTime')}</Typography>
          <LinearProgress determinate value={info ? info.currentPercent : 0} sx={{ mt: 2 }} />
          <Stack
            direction="row"
            justifyContent="space-between"
            alignItems="center"
            spacing={1}
            px={1}
            pt={1}
          >
            <Typography level="body-md">
              <Typography color="neutral">{t('vesting.nextPeriod')}:</Typography>{' '}
              {vesting.state === 'hasValue' && vesting.contents && info ? (
                info.isFinished ? (
                  t('vesting.contractFinished')
                ) : (
                  spDayjs(info.nextPeriod * 1000).format(START_TIME_FORMAT)
                )
              ) : (
                <Skeleton animation="wave" sx={{ opacity: 0.2 }} variant="rectangular">
                  {START_TIME_FORMAT}
                </Skeleton>
              )}
            </Typography>
            <Typography level="title-sm">
              {vesting.state === 'hasValue' && vesting.contents && info && !info.isFinished ? (
                <>
                  {info.currentPeriod}&nbsp;/&nbsp;{info.periods}
                </>
              ) : (
                ''
              )}
            </Typography>
          </Stack>
        </CardContent>
        <Divider sx={{ my: 2 }} />
        <CardContent sx={{ textAlign: { xs: 'center', md: 'left' } }}>
          <Typography level="title-lg" mb={2}>
            {t('vesting.params')}
          </Typography>
          <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
            <Typography color="neutral">{t('vesting.totalDuration')}</Typography>
            <Typography sx={{ position: 'relative', overflow: 'hidden' }}>
              <Skeleton loading={vesting.state === 'loading'}>
                {spDayjs
                  .duration(vesting.contents?.data?.totalDuration || 0, 'second')
                  .humanize(true)}
              </Skeleton>
            </Typography>
          </Stack>
          <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
            <Typography color="neutral">{t('vesting.unlockPeriod')}</Typography>
            <Typography sx={{ position: 'relative', overflow: 'hidden' }}>
              <Skeleton loading={vesting.state === 'loading'}>
                {spDayjs.duration(vesting.contents?.data?.unlockPeriod || 0, 'second').humanize()}
              </Skeleton>
            </Typography>
          </Stack>
          <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
            <Typography color="neutral">{t('vesting.cliffDuration')}</Typography>
            <Typography sx={{ position: 'relative', overflow: 'hidden' }}>
              <Skeleton loading={vesting.state === 'loading'}>
                {(vesting.contents?.data?.cliffDuration || 0) > 0
                  ? spDayjs
                      .duration(vesting.contents?.data?.cliffDuration || 0, 'second')
                      .humanize()
                  : t('vesting.cliffDisabled')}
              </Skeleton>
            </Typography>
          </Stack>
        </CardContent>
        <Divider sx={{ my: 2 }} />
        <CardContent sx={{ textAlign: { xs: 'center', md: 'left' } }}>
          <Typography level="body-lg">{t('jetton.vesting-balance')}</Typography>
          <Typography
            fontSize="xl4"
            fontWeight="xl"
            mt={1}
            sx={{ position: 'relative', overflow: 'hidden' }}
          >
            <Skeleton loading={false}>
              {info?.balance || '0'}{' '}
              <Typography textColor="neutral.400" fontSize="67.5%">
                vSP
              </Typography>
            </Skeleton>
          </Typography>
          <Typography level="inherit" sx={{ position: 'relative', overflow: 'hidden' }}>
            <Skeleton loading={false}>
              {t('vesting.available-for-claim')}: ~ {Number(info?.estUnlocked).toLocaleString()} vSP
            </Skeleton>
          </Typography>
          <Button
            disabled={!walletRestored || !info?.balance}
            variant="soft"
            size="lg"
            fullWidth
            sx={{ borderRadius: 6, py: 2, mt: 1 }}
            onClick={() => setOpenClaimForm(true)}
          >
            {t('vesting.button-claim')}
          </Button>
        </CardContent>
      </Card>
      <ModalDirectClaimForm
        open={openClaimForm}
        setOpen={setOpenClaimForm}
        data={vesting.contents?.data}
        loading={vesting.state === 'loading'}
      />
    </Box>
  );
};
