import { mnemonicNew, mnemonicToWalletKey, mnemonicValidate, mnemonicWordList } from '@ton/crypto';
import { WalletContractV4 } from '@ton/ton';
import { useCallback, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useRecoilState } from 'recoil';
import { useBiometrySecureStorage } from '/src/hooks';
import { walletsAtom } from '/src/state';
import { WalletType } from '/src/types';
import { delay } from '/src/utils';

type PhraseWord = {
  word: string;
  valid: boolean;
};

export const useWalletModal = (operation: 'import' | 'generate') => {
  const { t } = useTranslation();
  const {
    errorMessage,
    isMounting,
    isAccessGranted,
    isAuthenticated,
    authenticating,
    authenticateStorage,
    addRecord,
  } = useBiometrySecureStorage();
  const [myWallets, setMyWallets] = useRecoilState(walletsAtom);
  const [phrase, setPhrase] = useState<PhraseWord[]>();
  const [phraseCount, setPhraseCount] = useState<12 | 24>(24);
  const [phraseValid, setPhraseValid] = useState(false);
  const [retryMessage, setRetryMessage] = useState<string>();
  const [walletName, setWalletName] = useState(t('wallets.wallet-name'));
  const [generating, setGenerating] = useState(false);
  const generatePhrase = useCallback(async () => {
    setGenerating(true);
    const mnemonic = await mnemonicNew(phraseCount);
    await delay(1e3);
    setPhrase(mnemonic.map((word) => ({ word, valid: true })));
    setGenerating(false);
  }, [phraseCount]);
  const finishAddOrImport = useCallback(
    async (onClose: (v: boolean) => void) => {
      if (!phrase) return;
      const mnemonic = phrase.map((m) => m.word);
      const { publicKey } = await mnemonicToWalletKey(mnemonic);
      const walletContract = WalletContractV4.create({ publicKey, workchain: 0 });
      if (!walletContract) return;
      const address = walletContract.address.toRawString();

      if (errorMessage) {
        setRetryMessage(errorMessage);
        return;
      }
      if (!isAccessGranted) {
        setRetryMessage('retry with biometry');
        return;
      }
      const insertResult = await addRecord(mnemonic);
      if (insertResult) {
        setMyWallets((v) => [
          ...v
            // filter same address wallet
            .filter((f) => f.address != address)
            // deactivate other wallets
            .map((m) => ({ ...m, active: false })),
          // push fresh active wallet
          {
            address,
            active: true,
            name: walletName.substring(0, 24),
            wallet: WalletType.bip39,
            // phrase: mnemonic.join(','),
          },
        ]);
        setRetryMessage(undefined);
        onClose(false);
      } else {
        setRetryMessage(t('retry with biometry'));
      }
    },
    [phrase, errorMessage, isAccessGranted, addRecord],
  );

  const phraseChange = useCallback(
    (idx: number, word: string) =>
      setPhrase((p) => {
        if (!p) return;
        p[idx] = { word, valid: mnemonicWordList.indexOf(word) != -1 };
        return [...p];
      }),
    [phraseCount],
  );

  useEffect(() => {
    (async () => phrase && setPhraseValid(await mnemonicValidate(phrase.map((m) => m.word))))();
  }, [phrase]);

  useEffect(() => {
    setWalletName((v) => `${v}${myWallets.length + 1}`);
  }, [myWallets]);

  useEffect(() => {
    if (operation == 'import') {
      return setPhrase(Array(phraseCount).fill({ word: '', valid: true }));
    }
    (async () => {
      const p = await mnemonicNew(phraseCount);
      setPhrase(p.map((word) => ({ word, valid: true })));
    })();
  }, [operation, phraseCount]);

  return {
    phrase,
    generatePhrase,
    phraseCount,
    phraseChange,
    phraseValid,
    setPhraseCount,
    myWallets,
    finishAddOrImport,
    walletName,
    setWalletName,
    generating,
    setGenerating,
    isMounting,
    isAccessGranted,
    isAuthenticated,
    authenticating,
    authenticateStorage,
    retryMessage,
  };
};
