import { isTMA, retrieveLaunchParams } from '@telegram-apps/sdk-react';
import { selector } from 'recoil';

export const tmaLaunchParamsSelector = selector({
  key: 'tmaLaunchParamsSelector',
  get: async () => {
    try {
      if (await isTMA()) {
        return retrieveLaunchParams();
      }
    } catch (error) {}
  },
});
