import { Check, InfoOutlined } from '@mui/icons-material';
import {
  Button,
  Card,
  CardContent,
  DialogContent,
  DialogTitle,
  FormControl,
  FormHelperText,
  FormLabel,
  IconButton,
  Input,
  Modal,
  ModalDialog,
  Skeleton,
  Stack,
  Tooltip,
  Typography,
} from '@mui/joy';
import { FormEvent, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { DEFAULT_DECIMAL_PLACES } from '/src/constants';
import { usePrimaryWallet, useProvideStake } from '/src/hooks';
import { Asset } from '/src/types';
import { fromUnits, toUnits } from '/src/units';
import { friendlyAmount } from '/src/utils';

type Props = {
  open: boolean;
  setOpen: (v: boolean) => void;
  staking?: Asset;
  loading: boolean;
};

export const ModalStakeForm = ({ open, setOpen, staking, loading }: Props) => {
  const { t } = useTranslation();
  const { friendlyBalance, jetton, spintria } = usePrimaryWallet();
  const { amount, closeForm, setAmount, sendingTx, sendProvideStakeAction } = useProvideStake(
    jetton.data,
  );
  const decimals = DEFAULT_DECIMAL_PLACES;
  const estEarning = useMemo(() => {
    if (!staking || !staking?.staking?.fixed_apy) return;
    let value = Number(amount);
    value = Number.isNaN(value) ? 0 : value;
    const bigV = toUnits(value.toFixed(), decimals);
    return fromUnits(
      ((bigV * staking?.staking?.fixed_apy) / 100n / 365n) * BigInt(staking?.staking?.lockup || 30),
      decimals,
    );
  }, [amount, staking]);

  return (
    <Modal open={open} onClose={() => setOpen(false)}>
      <ModalDialog
        sx={(theme) => ({
          [theme.breakpoints.only('xs')]: {
            top: 0,
            bottom: 'unset',
            left: 0,
            right: 0,
            borderRadius: 0,
            transform: 'none',
            maxWidth: 'unset',
          },
        })}
      >
        <DialogTitle>{t('staking.form.title')}</DialogTitle>
        <DialogContent>{t('staking.form.description')}</DialogContent>
        <form
          onSubmit={(event: FormEvent<HTMLFormElement>) => {
            event.preventDefault();
            setOpen(false);
          }}
        >
          <Stack spacing={2}>
            <FormControl size="lg">
              <FormLabel sx={{ width: '100%' }}>
                <Stack
                  width="100%"
                  direction="row"
                  justifyContent="space-between"
                  alignItems="center"
                  gap={1}
                >
                  <Typography>{t('staking.form.amount')}</Typography>
                  <Stack direction="row" gap={1}>
                    <Typography
                      textColor="neutral.400"
                      sx={{ position: 'relative', overflow: 'hidden' }}
                    >
                      <Skeleton loading={loading}>
                        {t('staking.form.balance')}:{' '}
                        {(friendlyBalance - Number(amount)).toLocaleString()}
                      </Skeleton>
                    </Typography>
                    <Button
                      disabled={
                        loading ||
                        closeForm ||
                        sendingTx ||
                        !friendlyBalance ||
                        friendlyBalance === 0 ||
                        !staking ||
                        !staking.staking
                      }
                      variant="soft"
                      sx={{ py: 0.1, px: 1, minHeight: 25 }}
                      onClick={() => setAmount(friendlyBalance.toString())}
                    >
                      {t('staking.form.button-max')}
                    </Button>
                  </Stack>
                </Stack>
              </FormLabel>
              <Input
                disabled={
                  loading ||
                  closeForm ||
                  sendingTx ||
                  !friendlyBalance ||
                  friendlyBalance === 0 ||
                  !staking ||
                  !staking.staking
                }
                autoFocus
                required
                endDecorator={spintria?.value.content?.symbol}
                value={amount}
                onChange={(e) => {
                  let value = Number(e.currentTarget.value);
                  value = Number.isNaN(value) ? 0 : value;
                  const bigV = toUnits(value.toFixed(), decimals);
                  const realBalance = jetton?.data?.balance.value || 0n;
                  setAmount(bigV > realBalance ? friendlyBalance.toString() : value.toFixed());
                }}
              />
            </FormControl>
            <Card variant="soft" sx={{ width: '100%' }}>
              <CardContent sx={{ textAlign: 'center' }}>
                <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
                  <Tooltip title={t('staking.form.apy-info')} variant="solid">
                    <Typography
                      endDecorator={
                        <InfoOutlined color="secondary" sx={{ width: 18, height: 18 }} />
                      }
                    >
                      {t('staking.form.apy')}
                    </Typography>
                  </Tooltip>
                  <Typography sx={{ position: 'relative', overflow: 'hidden' }}>
                    <Skeleton loading={loading}>
                      {staking?.staking?.fixed_apy.toLocaleString()}%
                    </Skeleton>
                  </Typography>
                </Stack>
                <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
                  <Typography>{t('staking.form.est-earning')}</Typography>
                  <Typography sx={{ position: 'relative', overflow: 'hidden' }}>
                    <Skeleton loading={loading}>
                      {Number(estEarning || 0).toLocaleString()}
                    </Skeleton>
                  </Typography>
                </Stack>
                <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
                  <Typography>{t('staking.form.min-stake')}</Typography>
                  <Typography sx={{ position: 'relative', overflow: 'hidden' }}>
                    <Skeleton loading={loading}>
                      {staking?.staking?.min_stake
                        ? friendlyAmount(staking?.staking?.min_stake)
                        : '0,0'}
                    </Skeleton>
                  </Typography>
                </Stack>
                <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
                  <Typography>{t('staking.form.max-stake')}</Typography>
                  <Typography sx={{ position: 'relative', overflow: 'hidden' }}>
                    <Skeleton loading={loading}>
                      {staking?.staking?.max_stake
                        ? friendlyAmount(staking?.staking?.max_stake)
                        : '0,0'}
                    </Skeleton>
                  </Typography>
                </Stack>
              </CardContent>
            </Card>
            <FormHelperText sx={{ p: 0 }}>{t('staking.form.helper')}</FormHelperText>
            {!!(Number(amount) > 0) &&
              (jetton?.data?.balance.value || 0n) < (staking?.staking?.min_stake || 0n) && (
                <FormHelperText sx={{ px: 0, color: (t) => t.vars.palette.danger.plainColor }}>
                  {t('staking.form.min-stake-required')}{' '}
                  {staking?.staking?.min_stake
                    ? friendlyAmount(staking?.staking?.min_stake)
                    : '0,0'}{' '}
                  {spintria?.value.content?.symbol}
                </FormHelperText>
              )}
            {closeForm ? (
              <IconButton color="success" onClick={() => setOpen(false)}>
                <Check />
              </IconButton>
            ) : (
              <Button
                size="lg"
                type="submit"
                loading={sendingTx}
                disabled={
                  loading ||
                  closeForm ||
                  !staking ||
                  !staking.staking ||
                  !friendlyBalance ||
                  friendlyBalance === 0 ||
                  !amount ||
                  !Number(amount) ||
                  toUnits(amount, decimals) < staking.staking.min_stake ||
                  toUnits(amount, decimals) > staking.staking?.max_stake
                }
                onClick={() => sendProvideStakeAction()}
              >
                {t('staking.form.button-stake')}
              </Button>
            )}
          </Stack>
        </form>
      </ModalDialog>
    </Modal>
  );
};
