import {
  Avatar,
  List,
  ListItem,
  ListItemButton,
  ListItemContent,
  ListItemDecorator,
  Modal,
  ModalDialog,
  Sheet,
  Stack,
  Typography,
} from '@mui/joy';
import { useTranslation } from 'react-i18next';
import { WalletJettonsBalances } from '/src/types';
import { fromUnits } from '/src/units';
import { isTransferableJetton } from '/src/utils';

type Props = {
  open: boolean;
  balances?: WalletJettonsBalances['data']['balances'];
  onClose: () => void;
  onSelect: (jetton: WalletJettonsBalances['data']['balances'][number]) => void;
};

export const JettonPickerModal = ({ open, onSelect, onClose, balances }: Props) => {
  const { t } = useTranslation();
  return (
    <Modal open={open} onClose={() => onClose()}>
      <ModalDialog sx={{ p: 1 }}>
        <Sheet
          variant="plain"
          sx={{
            // maxHeight: 250,
            minWidth: 320,
            overflow: 'auto',
            borderRadius: 'sm',
            '::-webkit-scrollbar': { width: 8 },
            '::-webkit-scrollbar-thumb': { borderRadius: 4, background: '#888a' },
          }}
        >
          <List
            sx={{
              p: 0,
              '--List-gap': '12px',
              '--ListItemDecorator-size': '56px',
            }}
          >
            {balances
              ?.filter(
                (f) =>
                  Number(f.balance) > 0 && isTransferableJetton(f.jetton.address.toRawString()),
              )
              ?.map((m) => {
                // const transferable = isTransferableJetton(m.jetton.address.toRawString());
                return (
                  <ListItem key={`jetton-${m.jetton.address}`}>
                    <ListItemButton onClick={() => onSelect(m)}>
                      <ListItemDecorator>
                        <Avatar src={m.jetton.image} />
                      </ListItemDecorator>
                      <ListItemContent>
                        <Typography level="title-md">
                          {m.jetton.symbol}
                          {/* {!transferable && (
                            <Chip variant="outlined" component="span">
                              {t('send.not-transferable')}
                            </Chip>
                          )} */}
                        </Typography>
                        <Typography level="body-sm" sx={{ color: '#888c' }} noWrap>
                          {m.jetton.name}
                        </Typography>
                      </ListItemContent>
                      <Stack direction="column" alignItems="end">
                        <Typography level="title-md" noWrap endDecorator={m.jetton.symbol}>
                          {Number(fromUnits(m.balance, m.jetton.decimals)).toLocaleString(
                            undefined,
                            {
                              notation: 'compact',
                              maximumFractionDigits: 2,
                            },
                          )}
                        </Typography>
                      </Stack>
                    </ListItemButton>
                  </ListItem>
                );
              })}
          </List>
        </Sheet>
      </ModalDialog>
    </Modal>
  );
};
