import {
  Box,
  Button,
  Card,
  CardContent,
  Divider,
  LinearProgress,
  Skeleton,
  Stack,
  Typography,
} from '@mui/joy';
import { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { BodyTitle } from './body-title';
import { ModalClaimForm } from './modal-claim-form';
import { DEFAULT_DECIMAL_PLACES, NOW, START_TIME_FORMAT } from '/src/constants';
import { useVestingWallet } from '/src/hooks/useVestingWallet';
import { spDayjs } from '/src/libs';
import { fromUnits } from '/src/units';
import { getLocked } from '/src/utils';

export const VestingJettonInfo = () => {
  const { t } = useTranslation();
  const { friendlyVesting, wallet, vestingJetton, state } = useVestingWallet();
  const [openClaimForm, setOpenClaimForm] = useState(false);
  const decimals = DEFAULT_DECIMAL_PLACES;
  const vjBalance = useMemo(
    () =>
      vestingJetton && vestingJetton.balance
        ? Number(fromUnits(vestingJetton.balance, decimals))
        : 0,
    [vestingJetton],
  );
  const estUnlocked = useMemo(() => {
    if (
      !friendlyVesting ||
      !friendlyVesting.data ||
      !vestingJetton ||
      !vestingJetton.balance ||
      !vestingJetton.deposit
    ) {
      return 0;
    }
    const { balance, deposit } = vestingJetton;
    const { startTime, totalDuration, unlockPeriod, cliffDuration } = friendlyVesting.data;
    const locked = getLocked(
      BigInt(NOW()),
      deposit,
      BigInt(startTime),
      BigInt(totalDuration),
      BigInt(unlockPeriod),
      BigInt(cliffDuration),
    );
    const toClaim = deposit - (deposit - balance) - locked;

    return toClaim > 0 ? Number(fromUnits(toClaim, decimals)) : 0;
  }, [vestingJetton, friendlyVesting]);
  const tickerComponent = useMemo(
    () => (
      <Typography textColor="neutral.400" fontSize="67.5%">
        {friendlyVesting?.jetton?.content?.symbol}
      </Typography>
    ),
    [friendlyVesting],
  );

  if (!friendlyVesting) return;

  return (
    <Box>
      <BodyTitle />
      <Card variant="outlined" sx={{ width: '100%', boxShadow: 'none', border: 0 }}>
        <CardContent sx={{ textAlign: 'center' }}>
          <Typography level="h2">
            {spDayjs((friendlyVesting.data?.startTime || 0) * 1000).format(START_TIME_FORMAT)}
          </Typography>
          <Typography level="body-md">{t('vesting.startTime')}</Typography>
          <LinearProgress
            determinate
            value={friendlyVesting ? friendlyVesting.currentPercent : 0}
            sx={{ mt: 2 }}
          />
          <Stack
            direction="row"
            justifyContent="space-between"
            alignItems="center"
            spacing={1}
            px={1}
            pt={1}
          >
            <Typography level="body-md">
              <Typography color="neutral">{t('vesting.nextPeriod')}:</Typography>{' '}
              {friendlyVesting ? (
                friendlyVesting.isFinished ? (
                  t('vesting.contractFinished')
                ) : (
                  spDayjs(friendlyVesting.nextPeriod * 1000).format(START_TIME_FORMAT)
                )
              ) : (
                <Skeleton animation="wave" sx={{ opacity: 0.2 }} variant="rectangular">
                  {START_TIME_FORMAT}
                </Skeleton>
              )}
            </Typography>
            <Typography level="title-sm">
              {friendlyVesting && !friendlyVesting.isFinished ? (
                <>
                  {friendlyVesting.currentPeriod}&nbsp;/&nbsp;{friendlyVesting.periods}
                </>
              ) : (
                ''
              )}
            </Typography>
          </Stack>
        </CardContent>
        <Divider sx={{ my: 2 }} />
        <CardContent sx={{ textAlign: { xs: 'center', md: 'left' } }}>
          <Typography level="title-lg" mb={2}>
            {t('vesting.params')}
          </Typography>
          <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
            <Typography color="neutral">{t('vesting.totalDuration')}</Typography>
            <Typography sx={{ position: 'relative', overflow: 'hidden' }}>
              <Skeleton loading={state === 'loading'}>
                {spDayjs
                  .duration(friendlyVesting.data?.totalDuration || 0, 'second')
                  .humanize(true)}
              </Skeleton>
            </Typography>
          </Stack>
          <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
            <Typography color="neutral">{t('vesting.unlockPeriod')}</Typography>
            <Typography sx={{ position: 'relative', overflow: 'hidden' }}>
              <Skeleton loading={state === 'loading'}>
                {spDayjs.duration(friendlyVesting.data?.unlockPeriod || 0, 'second').humanize()}
              </Skeleton>
            </Typography>
          </Stack>
          <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
            <Typography color="neutral">{t('vesting.cliffDuration')}</Typography>
            <Typography sx={{ position: 'relative', overflow: 'hidden' }}>
              <Skeleton loading={state === 'loading'}>
                {(friendlyVesting.data?.cliffDuration || 0) > 0
                  ? spDayjs.duration(friendlyVesting.data?.cliffDuration || 0, 'second').humanize()
                  : t('vesting.cliffDisabled')}
              </Skeleton>
            </Typography>
          </Stack>
        </CardContent>
        <Divider sx={{ my: 2 }} />
        <CardContent sx={{ textAlign: { xs: 'center', md: 'left' } }}>
          <Typography level="body-lg">{t('jetton.vesting-jetton-balance')}</Typography>
          <Typography
            fontSize="xl4"
            fontWeight="xl"
            mt={1}
            sx={{ position: 'relative', overflow: 'hidden' }}
          >
            <Skeleton loading={false}>
              {vjBalance || '0'} {tickerComponent}
            </Skeleton>
          </Typography>
          <Typography level="inherit" sx={{ position: 'relative', overflow: 'hidden' }}>
            <Skeleton loading={false}>
              {t('vesting.available-for-claim')}: ~ {estUnlocked.toLocaleString()}{' '}
              {friendlyVesting?.jetton?.content?.symbol}
            </Skeleton>
          </Typography>
          <Button
            disabled={!wallet || !vestingJetton?.balance || estUnlocked <= 0}
            variant="soft"
            size="lg"
            fullWidth
            sx={{ borderRadius: 6, py: 2, mt: 1 }}
            onClick={() => setOpenClaimForm(true)}
          >
            {t('vesting.button-claim')}
          </Button>
        </CardContent>
      </Card>
      <ModalClaimForm
        open={openClaimForm}
        setOpen={setOpenClaimForm}
        data={vestingJetton?.balance}
        loading={state === 'loading'}
      />
    </Box>
  );
};
