import { ImportExport, Wallet } from '@mui/icons-material';
import {
  Box,
  Button,
  Divider,
  FormControl,
  FormHelperText,
  FormLabel,
  Input,
  Stack,
  Typography,
} from '@mui/joy';
import { StonApiClient } from '@ston-fi/api';
import { DEX, pTON } from '@ston-fi/sdk';
import { Address } from '@ton/core';
import { useTonConnectModal } from '@tonconnect/ui-react';
import throttle from 'lodash.throttle';
import { useCallback, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useRecoilValue, useSetRecoilState } from 'recoil';
import { SpLogo } from '../sp-logo';
import { TonLogo } from '../ton-logo';
import { WorkspaceNext } from '../workspace-next';
import {
  DEFAULT_DECIMAL_PLACES,
  FRACTION_DIGITS,
  MAINNET_SPINTRIA_MASTER_ADDRESS,
  NUMBER_COMPACT_TRIGGER_VALUE,
  TON_DEFAULT_DECIMAL_PLACES,
  TON_TICKER,
} from '/src/constants';
import { useActiveWallet, useLoadable, useTonConnect } from '/src/hooks';
import {
  currencyAtom,
  jettonSelector,
  metricsAtom,
  ratesSelector,
  tonClientSelector,
  walletSelector,
} from '/src/state';
import { appCurrencies } from '/src/types';
import { fromUnits, toUnits } from '/src/units';
import { clearInputAmoutValue, delay, waitForSeqno } from '/src/utils';

type SimulateSwap = {
  askAddress: string;
  askJettonWallet: string;
  askUnits: string;
  feeAddress: string;
  feePercent: string;
  feeUnits: string;
  minAskUnits: string;
  offerAddress: string;
  offerJettonWallet: string;
  offerUnits: string;
  poolAddress: string;
  priceImpact: string;
  routerAddress: string;
  slippageTolerance: string;
  swapRate: string;
};

const stonApiClient = new StonApiClient();

export const SwapScreen = () => {
  const { t } = useTranslation();
  const { open: openTonConnectModal } = useTonConnectModal();
  const setMetrics = useSetRecoilState(metricsAtom);
  const client = useLoadable(tonClientSelector);
  const { sender } = useTonConnect();
  const { walletRestored } = useActiveWallet();
  const [sendingTx, setSendingTx] = useState(false);
  const [tonAmount, setTonAmount] = useState('');
  const [spAmount, setSpAmount] = useState('');
  const [minAskUnits, setMinAskUnits] = useState('1');
  // const [simulateSwap, setSimulateSwap] = useState<SimulateSwap>();
  const jetton = useLoadable(jettonSelector(MAINNET_SPINTRIA_MASTER_ADDRESS));
  const tonRates = useLoadable(ratesSelector({ address: TON_TICKER }));
  const spRates = useLoadable(ratesSelector({ address: MAINNET_SPINTRIA_MASTER_ADDRESS }));
  const currency = useRecoilValue(currencyAtom);
  const tonAmountByCurrency = useMemo(
    () => (tonRates?.prices ? Number(tonAmount || 0) * tonRates.prices[currency] : 0),
    [currency, tonRates, tonAmount],
  );
  const spAmountByCurrency = useMemo(
    () => (spRates?.prices ? Number(spAmount || 0) * spRates.prices[currency] : 0),
    [currency, spRates, spAmount],
  );
  const jettonBalance = useMemo(
    () => (jetton ? Number(fromUnits(jetton.balance, DEFAULT_DECIMAL_PLACES)) : 0),
    [jetton],
  );
  const account = useLoadable(walletSelector);
  const accountBalance = useMemo(
    () => (account ? Number(fromUnits(account.balance, TON_DEFAULT_DECIMAL_PLACES)) : 0),
    [account],
  );
  const handleChange = useCallback(
    (
      value: string,
      changeValue: string,
      onChange?: (value?: string) => void,
      decimals = FRACTION_DIGITS,
    ) => {
      const inputValue = changeValue.trim();
      const newValue = clearInputAmoutValue(inputValue, decimals);
      const isEmpty = inputValue === '';
      if ((newValue || isEmpty) && newValue !== value) {
        onChange?.(newValue);
      }
    },
    [],
  );

  const swapHandler = useCallback(async () => {
    if (!client) return;
    if (!walletRestored) return;

    const dex = client.open(new DEX.v1.Router());
    const waiter = await waitForSeqno(client, Address.parse(walletRestored.address));

    let senderFail = false;
    setSendingTx(true);
    try {
      const txParams = await dex.getSwapTonToJettonTxParams({
        userWalletAddress: walletRestored.address,
        proxyTon: new pTON.v1(),
        offerAmount: toUnits(tonAmount, TON_DEFAULT_DECIMAL_PLACES),
        askJettonAddress: MAINNET_SPINTRIA_MASTER_ADDRESS,
        minAskAmount: minAskUnits,
      });
      await sender?.send(txParams);
      setMetrics((v) => ({ ...v, swap: { ton: tonAmount, sp: spAmount } }));
    } catch (error) {
      senderFail = true;
    }

    if (senderFail) {
      setSendingTx(false);
      return;
    }

    try {
      await waiter();
      await delay(10e3);
    } catch (error) {}

    setSendingTx(false);
  }, [walletRestored, client, tonAmount, spAmount, minAskUnits]);

  const throttledSimulateSwap = useCallback(
    throttle(
      async ({ askUnits, offerUnits }: { askUnits?: string; offerUnits?: string }) => {
        const askAddress = MAINNET_SPINTRIA_MASTER_ADDRESS;
        /**
         * EQAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAM9c in STONfi means
         * master TON jetton address
         */
        const offerAddress = 'EQAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAM9c';
        /**
         * What is slippage tolerance? Slippage tolerance is a setting in
         * trading platforms that allows you to determine how much price
         * slippage you're willing to accept so that your order can be
         * executed. If the market does slip, and you haven't set a price
         * tolerance, your broker will just accept the next available market
         * price.
         *
         * The maximum possible difference between the rates that we expect and
         * which will actually be, in fractions (for example, 0.001 is 0.1%)
         */
        const slippageTolerance = '0.01'; // 1% ?
        try {
          if (askUnits) {
            const response = await stonApiClient.simulateReverseSwap({
              askAddress,
              askUnits,
              offerAddress,
              slippageTolerance,
            });
            if (response) {
              setTonAmount(fromUnits(response.offerUnits, TON_DEFAULT_DECIMAL_PLACES));
              setMinAskUnits(response.minAskUnits);
              setMetrics((v) => ({
                ...v,
                simulate: { sp: askUnits, ton: response.offerUnits },
              }));
            }
          } else if (offerUnits) {
            const response = await stonApiClient.simulateSwap({
              askAddress,
              offerAddress,
              offerUnits,
              slippageTolerance,
            });
            if (response) {
              setSpAmount(fromUnits(response.askUnits, DEFAULT_DECIMAL_PLACES));
              setMinAskUnits(response.minAskUnits);
              setMetrics((v) => ({
                ...v,
                simulate: { sp: response.askUnits, ton: offerUnits },
              }));
            }
          }
        } catch (error) {}
      },
      1e3,
      { trailing: true, leading: true },
    ),
    [],
  );

  return (
    <WorkspaceNext>
      {/* swap */}
      <Stack spacing={2}>
        <Box>
          <Typography level="h3">{t('swap.title')}</Typography>
          <Typography level="body-sm">{t('swap.subtitle')}</Typography>
        </Box>
        <FormControl size="lg">
          <FormLabel sx={{ width: '100%', pr: 1 }}>
            <Stack
              width="100%"
              direction="row"
              justifyContent="space-between"
              alignItems="center"
              gap={1}
            >
              <Typography>{t('swap.you-send')}</Typography>
              <Typography
                textColor="neutral.400"
                startDecorator={<Wallet sx={{ width: 16, height: 16, color: '#8888' }} />}
                endDecorator={<Typography sx={{ color: '#8888' }}>TON</Typography>}
              >
                {accountBalance
                  ? accountBalance.toLocaleString(undefined, {
                      notation:
                        accountBalance > NUMBER_COMPACT_TRIGGER_VALUE ? 'compact' : 'standard',
                      maximumFractionDigits: 4,
                    })
                  : '-'}
              </Typography>
            </Stack>
          </FormLabel>
          <Input
            placeholder="0.00"
            disabled={sendingTx || !walletRestored}
            autoFocus
            required
            endDecorator={
              <Typography endDecorator={<TonLogo sx={{ width: 32, height: 32 }} />}>TON</Typography>
            }
            value={tonAmount}
            onChange={(e) =>
              handleChange(
                tonAmount,
                e.currentTarget.value,
                (value = '') => {
                  const bigV = toUnits(value || '', TON_DEFAULT_DECIMAL_PLACES);
                  const realBalance = account?.balance || 0n;
                  const amount =
                    bigV > realBalance ? fromUnits(realBalance, TON_DEFAULT_DECIMAL_PLACES) : value;
                  setTonAmount(amount);
                  if (Number(amount) > 0) {
                    throttledSimulateSwap({
                      offerUnits: toUnits(amount, TON_DEFAULT_DECIMAL_PLACES).toString(),
                    });
                  }
                },
                TON_DEFAULT_DECIMAL_PLACES,
              )
            }
            sx={{
              fontSize: '150%',
              '--Input-minHeight': '60px',
              '--Input-placeholderOpacity': 0.3,
            }}
          />
          <FormHelperText sx={{ px: 2 }}>
            {appCurrencies[currency].symbol}
            {tonAmountByCurrency.toLocaleString(undefined, {
              notation: tonAmountByCurrency > NUMBER_COMPACT_TRIGGER_VALUE ? 'compact' : 'standard',
              maximumFractionDigits: 1,
            })}
          </FormHelperText>
        </FormControl>
        <Divider sx={{ pt: 1 }}>
          <ImportExport />
        </Divider>
        <FormControl size="lg">
          <FormLabel sx={{ width: '100%', pr: 1 }}>
            <Stack
              width="100%"
              direction="row"
              justifyContent="space-between"
              alignItems="center"
              gap={1}
            >
              <Typography>{t('swap.you-receive')}</Typography>
              <Typography
                textColor="neutral.400"
                startDecorator={<Wallet sx={{ width: 16, height: 16, color: '#8888' }} />}
                endDecorator={<Typography sx={{ color: '#8888' }}>SP</Typography>}
              >
                {jetton
                  ? jettonBalance.toLocaleString(undefined, {
                      notation:
                        jettonBalance > NUMBER_COMPACT_TRIGGER_VALUE ? 'compact' : 'standard',
                      maximumFractionDigits: 4,
                    })
                  : '-'}
              </Typography>
            </Stack>
          </FormLabel>
          <Input
            placeholder="0.00"
            disabled={sendingTx || !walletRestored}
            required
            endDecorator={
              <Typography endDecorator={<SpLogo sx={{ width: 32, height: 32 }} />}>SP</Typography>
            }
            value={spAmount}
            onChange={(e) =>
              handleChange(
                spAmount,
                e.currentTarget.value,
                (value = '') => {
                  const bigV = toUnits(value || '', DEFAULT_DECIMAL_PLACES);
                  const realBalance = BigInt(jetton?.balance || 0n);
                  const amount =
                    bigV > realBalance ? fromUnits(realBalance, DEFAULT_DECIMAL_PLACES) : value;
                  setSpAmount(amount);
                  if (Number(amount) > 0) {
                    throttledSimulateSwap({
                      askUnits: toUnits(amount, DEFAULT_DECIMAL_PLACES).toString(),
                    });
                  }
                },
                DEFAULT_DECIMAL_PLACES,
              )
            }
            sx={{
              fontSize: '150%',
              '--Input-minHeight': '60px',
              '--Input-placeholderOpacity': 0.3,
            }}
          />
          <FormHelperText sx={{ px: 2 }}>
            {appCurrencies[currency].symbol}
            {spAmountByCurrency.toLocaleString(undefined, {
              notation: spAmountByCurrency > NUMBER_COMPACT_TRIGGER_VALUE ? 'compact' : 'standard',
              maximumFractionDigits: 1,
            })}
          </FormHelperText>
        </FormControl>

        {walletRestored ? (
          <Button
            size="lg"
            type="submit"
            loading={sendingTx}
            disabled={
              !client ||
              !walletRestored ||
              !tonAmount ||
              !Number(tonAmount) ||
              toUnits(tonAmount, TON_DEFAULT_DECIMAL_PLACES) <= 0 ||
              !spAmount ||
              !Number(spAmount) ||
              toUnits(spAmount, DEFAULT_DECIMAL_PLACES) <= 0
            }
            onClick={() => swapHandler()}
          >
            {t('swap.buy')}
          </Button>
        ) : (
          <Button onClick={() => openTonConnectModal()}>{t('connect-wallet')}</Button>
        )}
      </Stack>
    </WorkspaceNext>
  );
};
