import { JettonBalance } from '@ton-api/client';
import { useEffect, useState } from 'react';
import { useSetRecoilState } from 'recoil';
import { VESTING_CONTRACTS_LIST } from '../constants';
import { pushToSnacks, snacksAtom, tonApiClient } from '../state';
import { delay, getAddress } from '../utils';
import { useActiveWallet } from './useActiveWallet';

const vestingJettons = Object.values(VESTING_CONTRACTS_LIST)
  .map(getAddress)
  .filter((f) => !!f);
const findJettons = async (wallet: string) => {
  const jettons: JettonBalance[] = [];
  const address = getAddress(wallet);
  if (!address) return jettons;
  for (const jetton of vestingJettons) {
    if (!jetton) continue;
    try {
      const data = await tonApiClient.accounts.getAccountJettonBalance(address, jetton);
      jettons.push(data);
    } catch (error) {}
    await delay(3e3);
  }
  return jettons;
};

export function useVestingFinder() {
  const { walletRestored } = useActiveWallet();
  const setSnacks = useSetRecoilState(snacksAtom);
  const [jettons, setJettons] = useState<JettonBalance[]>([]);
  const [pending, setPending] = useState(true);
  const [retry, setRetry] = useState(true);

  useEffect(() => {
    if (!walletRestored || !retry) return;
    setRetry(false);
    setPending(true);
    findJettons(walletRestored.address)
      .then(setJettons)
      .catch((e) => {
        console.info(e);
        setSnacks(
          pushToSnacks({
            color: 'neutral',
            title: 'Info',
            body: 'Unable to find vesting jettons',
          }),
        );
      })
      .finally(() => setPending(false));
  }, [walletRestored, retry]);

  return { jettons, pending, setRetry };
}
