export const isUnderTelegramWebview =
  typeof window.TelegramWebviewProxy === 'object' &&
  typeof window.TelegramWebviewProxy.postEvent === 'function';

export const delay = (ms?: number) => new Promise((resolve) => setTimeout(resolve, ms));

export const truncateLong = (s: string, l = 20, separator = '...') => {
  if (s.length <= l) return s;
  const sepLen = separator.length,
    charsToShow = l - sepLen,
    frontChars = Math.ceil(charsToShow / 2),
    backChars = Math.floor(charsToShow / 2);
  return s.substring(0, frontChars) + separator + s.substring(s.length - backChars);
};

export const sleep = (ms: number | undefined) =>
  new Promise((resolve) => {
    setTimeout(resolve, ms);
  });

export const getAddress = (s: string) => {
  let a: Address | undefined = undefined;
  try {
    a = Address.parse(s);
  } catch (e) {
    // console.error('bad address', s, e);
  }
  return a;
};

export const findAddressInArray = (a: string[], b: string) => {
  const bA = getAddress(b);
  return bA && a.find((f) => getAddress(f)?.equals(bA));
};

type JettonMetaDataKeys = 'name' | 'description' | 'image' | 'symbol' | 'image_data' | 'decimals';
const jettonOnChainMetadataSpec: {
  [key in JettonMetaDataKeys]: 'utf8' | 'ascii' | undefined;
} = {
  name: 'utf8',
  description: 'utf8',
  image: 'ascii',
  decimals: 'utf8',
  symbol: 'utf8',
  image_data: undefined,
};

const getSeqNo = async (client: CustomTonClient, wallet: Address) => {
  if (client instanceof ContractAdapter) {
    const state = await client.provider(wallet).getState();
    let seqno = 0;
    if (state.state.type === 'active' && state.state.data) {
      const cells = Cell.fromBoc(state.state.data);
      if (cells.length > 0) {
        seqno = cells[0].beginParse().loadUint(32);
      }
    }
    return seqno;
  } else {
    const getMethodResult = await client.runMethod(wallet, 'seqno');
    return getMethodResult.stack.readNumber();
  }
};

export async function waitForSeqno(client: CustomTonClient, wallet: Address) {
  const seqnoBefore = await getSeqNo(client, wallet);

  return async () => {
    for (let attempt = 0; attempt < 15; attempt++) {
      await sleep(6e3);
      const seqnoAfter = await getSeqNo(client, wallet);

      if (seqnoAfter > seqnoBefore) return;
    }
    throw new Error('Timeout');
  };
}

const fetchMetadataUri = async (uri: string) => {
  try {
    const response = await fetch(uri, {
      method: 'GET',
      headers: { 'Content-Type': 'application/json' },
    });
    const rawJson = await response.json();
    if (instanceOfJettonMetadata(rawJson)) {
      return rawJson;
    }
  } catch (err) {
    // console.info('fetchMetadataUri', err);
  }
};

export const fetchAssets = async (client: CustomTonClient): Promise<Asset[]> => {
  const values: Asset[] = [];
  const minters: { smcType: SmcType; addrs: string[] }[] = [
    { smcType: 'jetton', addrs: [MAINNET_SPINTRIA_MASTER_ADDRESS] },
    { smcType: 'staking', addrs: Object.values(STAKING_FIXED_APY_LIST) },
    { smcType: 'vesting', addrs: Object.values(VESTING_CONTRACTS_LIST) },
  ];
  for (const minterBySmc of minters) {
    for (const minter of minterBySmc.addrs) {
      const address = getAddress(minter);
      if (!address) continue;
      const smc = client.open(new Jetton(address));
      const jetton = await smc.getJettonData();
      const content = await getJettonMetadata(jetton.content);
      let asset: Asset | undefined = undefined;
      if (content) {
        // NOTE: shitty CORS
        let offchainContent: JettonMetadata | undefined;
        if (content.uri?.indexOf(import.meta.env.VITE_HOMEPAGE) === 0) {
          const uri = import.meta.env.DEV
            ? content.uri.slice(import.meta.env.VITE_HOMEPAGE.length)
            : content.uri;
          offchainContent = await fetchMetadataUri(uri);
        }
        asset = {
          address: minter,
          smc: minterBySmc.smcType,
          timestamp: Date.now(),
          value: {
            content: { ...content, ...(offchainContent || {}) },
            totalSupply: jetton.totalSupply,
          },
        };
      }

      if (!asset) continue;

      switch (minterBySmc.smcType) {
        case 'staking': {
          const staking = await smc.getStakingData();
          if (!instanceOfStakingData(staking)) {
            console.error('Error getting staking data', minter);
          }
          asset.staking = staking;
          break;
        }
        case 'vesting': {
          const vesing = await smc.getVestingData();
          if (!instanceOfVestingData(vesing)) {
            console.error('Error getting vesting data', minter);
          }
          asset.vesting = vesing;
          break;
        }
        default:
          break;
      }
      values.push(asset);
    }
    await delay(5e2);
  }

  return values;
};

