export const getJettonAddress = async (
  client: CustomTonClient,
  minter: Address,
  wallet: Address,
) => {
  const contract = client.open(new Jetton(minter));
  try {
    const jettonA = await contract.getWalletAddress(wallet);
    if (!jettonA) return;
    return jettonA;
  } catch (error) {
    console.error('Jetton.getWalletAddress', error);
  }
};

export const getJettonBalance = async (client: CustomTonClient, jetton: Address, smc: SmcType) => {
  const contract = client.open(new JettonWallet(jetton));
  let value: bigint = 0n;
  let deposit: bigint | undefined = undefined;
  let stakeAt: number | undefined = undefined;
  try {
    const walletData = await contract.getWalletData();
    value = walletData.balance;
  } catch (error) {
    console.error(error);
    throw new Error('Failed to retrieve wallet data');
  }
  switch (smc) {
    case 'staking': {
      try {
        stakeAt = await contract.getStakeAt();
      } catch (error) {
        console.error(error);
        throw new Error('Failed to retrieve wallet stake at time');
      }
      break;
    }
    case 'vesting': {
      try {
        deposit = await contract.getDeposit();
      } catch (error) {
        console.error(error);
        throw new Error('Failed to retrieve wallet deposit value');
      }
      break;
    }
    case 'jetton':
    default:
      break;
  }
  return { value, deposit, stakeAt };
};

