export const getLocked = (
  from: bigint,
  deposit: bigint,
  start: bigint,
  duration: bigint,
  unlock: bigint,
  cliff: bigint,
) => {
  // at the end of locked period
  if (from > start + duration) {
    return 0n;
  }
  // less than cliff period
  if (from < start + cliff) {
    return deposit;
  }
  return deposit - (deposit * ((from - start) / unlock)) / (duration / unlock);
};

export const uuidv4 = () => {
  const uuid = new Array(36);
  for (let i = 0; i < 36; i++) {
    uuid[i] = Math.floor(Math.random() * 16);
  }
  uuid[14] = 4; // set bits 12-15 of time-high-and-version to 0100
  uuid[19] = uuid[19] &= ~(1 << 2); // set bit 6 of clock-seq-and-reserved to zero
  uuid[19] = uuid[19] |= 1 << 3; // set bit 7 of clock-seq-and-reserved to one
  uuid[8] = uuid[13] = uuid[18] = uuid[23] = '-';
  return uuid.map((x) => x.toString(16)).join('');
};

export const friendlyAmount = (value?: bigint, decimals?: string | number) =>
  Number(fromUnits(value || 0n, DEFAULT_DECIMAL_PLACES)).toLocaleString();

export const getSpintriaAccountsBySmcType = (smcType?: SmcType) => {
  switch (smcType) {
    case 'jetton':
      return [MAINNET_SPINTRIA_MASTER_ADDRESS];
    case 'staking':
      return Object.values(STAKING_FIXED_APY_LIST);
    case 'vesting':
      return Object.values(VESTING_CONTRACTS_LIST);
    default:
      return [
        MAINNET_SPINTRIA_MASTER_ADDRESS,
        ...Object.values(STAKING_FIXED_APY_LIST),
        ...Object.values(VESTING_CONTRACTS_LIST),
      ];
  }
};

export const getSpintriaAddresses = () =>
  getSpintriaAccountsBySmcType()
    .map(getAddress)
    .filter((f) => f !== undefined);

export const getInputAmountRegex = (decimals: number) => {
  if (!decimals) return /^(\d+)$/;
  return new RegExp(`^(\\d+)([.,])?(\\d{1,${decimals}})?`);
};

export const clearInputAmoutValue = (value: string, decimals: number) =>
  value
    .replace(',', '.') // Replace comma to point
    .replace(/[^\d.]/, '') // Remove incorrect symbols
    .match(getInputAmountRegex(decimals))?.[0] // Trim extra decimal places
    .replace(/^0+(?=([1-9]|0\.))/, '') // Trim extra zeros at beginning
    .replace(/^0+$/, '0') ?? ''; // Trim extra zeros (if only zeros are entered)

