import { Settings } from '@mui/icons-material';
import { Box, IconButton, Link, Stack, Typography } from '@mui/joy';
import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate, useParams } from 'react-router';
import { useConnectedWallet } from '../hooks';
import { RouteParams } from '../types';
import { SettingModal } from './settings-modal';
import { SnacksButton } from './snacks-button';
import { SpintriaLogo } from './spintria-logo';
import { WalletMenuBar } from './wallet-menu-bar';

export const MainHeader = () => {
  const { t } = useTranslation();
  const wallet = useConnectedWallet();
  const { address } = useParams<RouteParams>();
  const navigate = useNavigate();
  const [openSettings, setOpenSettings] = useState(false);

  useEffect(() => {
    if (address && wallet.state == 'hasValue' && !wallet.contents) {
      navigate('/');
    }
  }, [wallet, address]);

  return (
    <>
      <Box
        component="header"
        sx={{
          py: 2,
          pb: 5,
          display: 'flex',
          flexDirection: 'row',
          gap: 2,
          minWidth: '75%',
          maxWidth: '100%',
          mx: { md: 'auto' },
          justifyContent: 'space-between',
        }}
      >
        <Link
          sx={{
            gap: 1,
            display: { xs: 'none', md: 'flex' },
            alignItems: 'center',
            '&:hover': { textDecoration: 'none' },
          }}
          href={import.meta.env.BASE_URL}
        >
          <SpintriaLogo sx={{ width: 32, height: 32 }} />
          <Typography level="title-lg" sx={{ fontWeight: '400' }}>
            {t('company')}
          </Typography>
        </Link>
        <IconButton
          variant="soft"
          sx={{ display: { xs: 'inline-flex', md: 'none' } }}
          onClick={() => setOpenSettings(true)}
        >
          <Settings />
        </IconButton>
        <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
          <Box
            sx={{
              display: { xs: 'none', md: 'flex', flexDirection: 'row', gap: 6 },
            }}
          >
            <SnacksButton />
            <IconButton variant="soft" onClick={() => setOpenSettings(true)}>
              <Settings />
            </IconButton>
          </Box>
          <WalletMenuBar />
          {/* <TonConnectButton className="ton-connect-button" /> */}
        </Stack>
      </Box>
      <SettingModal open={openSettings} setOpen={setOpenSettings} />
    </>
  );
};
