import { AtomEffect, DefaultValue } from 'recoil';
import { StateStorage } from './utils/state-storage';

type PersistenceOptions<T> = {
  defaultValue?: T | DefaultValue;
  key: string;
  isValid: (value: T | DefaultValue) => boolean;
};

export const localStorageEffect = <T>({ defaultValue, key, isValid }: PersistenceOptions<T>) =>
  (({ setSelf, onSet, trigger }) => {
    const storage = new StateStorage<T>(key);

    if (trigger === 'get') {
      let value: DefaultValue | T = new DefaultValue();
      try {
        const parsedValue = storage.get();
        if (parsedValue && isValid(parsedValue)) {
          value = parsedValue;
        } else if (defaultValue) {
          value = defaultValue;
        }
      } catch (err) {
        console.info(`Can't JSON.parse value from`, key);
        storage.remove();
      }
      setSelf(value);
    }

    onSet((value, _, isReset) => {
      if (isReset || !isValid(value)) {
        storage.remove();
      } else {
        storage.set(value);
      }
    });
  }) as AtomEffect<T>;
